const app = getApp()
var commonUtil = require('../../utils/common-util.js')
Page({
  data: {
    content: '',
    remaining: 500,
    images: [],       // 本地临时路径
    video: null,      // 本地临时路径
    videoDuration: 0,
    uploading: false
  },

  bindContentInput: function(e) {
    this.setData({ content: e.detail.value, remaining: 500 - e.detail.value.length })
  },

  // 选择图片（最多4张）
  chooseImage: function() {
    var that = this
    var remaining = 4 - that.data.images.length
    if (remaining <= 0) {
      wx.showToast({ title: '最多4张图片', icon: 'none' })
      return
    }
    wx.chooseImage({
      count: remaining,
      sizeType: ['compressed'],
      sourceType: ['album', 'camera'],
      success: function(res) {
        var newImages = that.data.images.concat(res.tempFilePaths)
        that.setData({ images: newImages })
      }
    })
  },

  // 选择视频（最多1个，15秒限制）
  chooseVideo: function() {
    var that = this
    if (that.data.video) {
      wx.showToast({ title: '只能上传1个视频', icon: 'none' })
      return
    }
    wx.chooseVideo({
      sourceType: ['album', 'camera'],
      maxDuration: 15,
      compressed: true,
      camera: 'back',
      success: function(res) {
        // 如果视频太大（超过10MB），截取前15秒
        var size = res.size || 0
        var tempPath = res.tempFilePath
        if (size > 10 * 1024 * 1024) {
          wx.showToast({ title: '视频较大，正在压缩...', icon: 'none' })
          // 重新选择压缩版本
          wx.chooseMedia({
            count: 1,
            mediaType: ['video'],
            maxDuration: 15,
            sourceType: ['album', 'camera'],
            camera: 'back',
            success: function(res2) {
              var video = res2.tempFiles && res2.tempFiles[0]
              if (video) {
                that.setData({ video: video.tempFilePath, videoDuration: video.duration || 0 })
              }
            }
          })
        } else {
          that.setData({ video: tempPath, videoDuration: res.duration || 0 })
        }
      }
    })
  },

  // 删除图片
  removeImage: function(e) {
    var index = e.currentTarget.dataset.index
    var images = this.data.images
    images.splice(index, 1)
    this.setData({ images: images })
  },

  // 删除视频
  removeVideo: function() {
    this.setData({ video: null, videoDuration: 0 })
  },

  // 预览图片
  previewImage: function(e) {
    var url = e.currentTarget.dataset.url
    wx.previewImage({ urls: this.data.images, current: url })
  },

  // 上传所有媒体到云存储（图片先压缩到100KB以内，视频先压缩）
  uploadMedia: function() {
    var that = this
    var promises = []
    // 上传图片（先压缩）
    for (var i = 0; i < that.data.images.length; i++) {
      promises.push((function(filePath) {
        return new Promise(function(resolve) {
          commonUtil.compressImageToSize(filePath, 100).then(function(compressedPath) {
            var ext = compressedPath.split('.').pop() || 'jpg'
            var cloudPath = 'forum/images/' + Date.now() + '_' + Math.random().toString(36).substr(2, 6) + '.' + ext
            wx.cloud.uploadFile({
              cloudPath: cloudPath,
              filePath: compressedPath,
              success: function(res) { resolve({ type: 'image', url: res.fileID }) },
              fail: function() { resolve(null) }
            })
          }).catch(function() { resolve(null) })
        })
      })(that.data.images[i]))
    }
    // 上传视频（先压缩）
    if (that.data.video) {
      promises.push(new Promise(function(resolve) {
        var filePath = that.data.video
        commonUtil.compressVideo(filePath, 10).then(function(compressedPath) {
          var ext = compressedPath.split('.').pop() || 'mp4'
          var cloudPath = 'forum/videos/' + Date.now() + '_' + Math.random().toString(36).substr(2, 6) + '.' + ext
          wx.cloud.uploadFile({
            cloudPath: cloudPath,
            filePath: compressedPath,
            success: function(res) { resolve({ type: 'video', url: res.fileID }) },
            fail: function() { resolve(null) }
          })
        }).catch(function() { resolve(null) })
      }))
    }
    return Promise.all(promises)
  },

  submitPost: function() {
    var that = this
    var content = that.data.content.trim()
    if (!content && that.data.images.length === 0 && !that.data.video) {
      wx.showToast({ title: '请输入内容或上传媒体', icon: 'none' })
      return
    }
    if (that.data.uploading) return
    that.setData({ uploading: true })
    wx.showLoading({ title: '发布中...' })

    // 先上传媒体
    that.uploadMedia().then(function(mediaList) {
      var validMedia = mediaList.filter(function(m) { return m !== null })
      var userInfo = app.globalData.userInfo || {}

      wx.cloud.callFunction({
        name: 'login',
        data: {
          action: 'createPost',
          content: content,
          authorName: userInfo.nickName || '匿名用户',
          authorPhone: userInfo.phone || '',
          avatarColor: userInfo.avatarColor || '#0EA5E9',
          starPoints: userInfo.starPoints || 0,
          isAdmin: !!(userInfo.isAdmin),
          isManager: !!(userInfo.isManager),
          media: validMedia,
          coverImage: validMedia.length > 0 ? validMedia[0].url : '',
          school: userInfo.school || ''
        },
        success: function(res) {
          wx.hideLoading()
          that.setData({ uploading: false })
          if (res.result && res.result.code === 0) {
            wx.showToast({ title: '发布成功', icon: 'success' })
            setTimeout(function() { wx.navigateBack() }, 1500)
          } else {
            wx.showToast({ title: (res.result && res.result.msg) || '发布失败', icon: 'none' })
          }
        },
        fail: function() { wx.hideLoading(); that.setData({ uploading: false }); wx.showToast({ title: '网络错误', icon: 'none' }) }
      })
    })
  }
})
