// 云函数：确认送达
const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command

exports.main = async function(event, context) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID
  const orderId = event.orderId
  const photoUrl = event.photoUrl || ''
  const uploadType = event.uploadType || 'camera'
  const uploadTime = event.uploadTime || null

  if (!orderId) {
    return { code: -1, msg: '缺少订单ID' }
  }
  if (!photoUrl) {
    return { code: -1, msg: '请上传完成证明' }
  }

  try {
    const orderResult = await db.collection('orders').doc(orderId).get()
    if (!orderResult.data) {
      return { code: -1, msg: '订单不存在' }
    }
    const order = orderResult.data

    // 只有接单者可以确认完成
    if (order.acceptorId !== openid) {
      return { code: -1, msg: '只有接单者可以确认送达' }
    }
    if (order.status !== 'accepted') {
      return { code: -1, msg: '订单状态不正确' }
    }

    // 更新订单（原子条件更新，防止并发双加星分）
    var updateData = {
      status: 'delivered',
      deliveryPhoto: photoUrl,
      uploadType: uploadType,
      completeTime: db.serverDate()
    }
    if (uploadTime) {
      updateData.uploadTime = uploadTime
    }

    var updateResult = await db.collection('orders').where({
      _id: orderId,
      status: 'accepted'
    }).update({
      data: updateData
    })

    // 如果没有更新成功，说明订单状态已变（可能被并发请求处理了）
    if (updateResult.stats.updated === 0) {
      return { code: -1, msg: '订单状态不正确或已被处理' }
    }

    // 完成订单：双方各+1星分（基础分）
    // 只有更新成功才加星分，防止并发重复加
    if (order.publisherId) {
      await db.collection('users').where({ _openid: order.publisherId }).update({
        data: { starPoints: _.inc(1) }
      })
    }
    if (order.acceptorId) {
      await db.collection('users').where({ _openid: order.acceptorId }).update({
        data: { starPoints: _.inc(1) }
      })
    }

    // 注意：helpCount 在 acceptOrder 接单时已经 +1，这里不再重复递增

    return { code: 0, msg: '送达完成' }
  } catch (err) {
    return { code: -1, msg: '操作失败', err: err.message }
  }
}
