// 云函数：标记消息为已读
// 通过云函数更新，绕过客户端只能更新自己创建的消息的限制
const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command

exports.main = async function(event, context) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID
  const orderId = event.orderId

  if (!orderId) {
    return { code: -1, msg: '缺少订单ID' }
  }

  try {
    // 校验当前用户是否是该订单的发布者或接单者
    var orderRes = await db.collection('orders').doc(orderId).get()
    if (!orderRes.data) {
      return { code: -1, msg: '订单不存在' }
    }
    var order = orderRes.data
    if (order.publisherId !== openid && order.acceptorId !== openid) {
      return { code: -1, msg: '无权标记此订单消息' }
    }

    // 分两步更新：
    // 1. 更新 isRead 明确为 false 的消息
    await db.collection('messages').where({
      orderId: orderId,
      senderId: _.neq(openid),
      isRead: false
    }).update({
      data: { isRead: true }
    })

    // 2. 更新没有 isRead 字段的消息（兼容旧数据）
    await db.collection('messages').where({
      orderId: orderId,
      senderId: _.neq(openid),
      isRead: _.exists(false)
    }).update({
      data: { isRead: true }
    })

    return { code: 0, msg: '标记成功' }
  } catch (err) {
    return { code: -1, msg: '标记失败', err: err.message }
  }
}
