// getUserProfile/index.js
// 云函数：获取用户公开信息
const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()

exports.main = async function(event, context) {
  const targetOpenid = event.openid

  if (!targetOpenid) {
    return { code: -1, msg: '缺少用户标识' }
  }

  try {
    const userResult = await db.collection('users').where({ _openid: targetOpenid }).get()

    if (userResult.data.length === 0) {
      return { code: -1, msg: '用户不存在' }
    }

    var user = userResult.data[0]
    // 只返回公开信息
    var profile = {
      nickName: user.nickName || '匿名用户',
      avatarUrl: user.avatarUrl || '',
      building: user.building || '',
      floor: user.floor || '',
      room: user.room || '',
      rating: user.rating || 0,
      ratingCount: user.ratingCount || 0,
      orderCount: user.orderCount || 0,
      helpCount: user.helpCount || 0,
      isVerified: user.isVerified || false
    }

    return { code: 0, msg: '获取成功', data: profile }
  } catch (err) {
    return { code: -1, msg: '获取失败', err: err.message }
  }
}
