/**
 * 个人中心页逻辑
 */

var app = getApp()
var commonUtil = require('../../utils/common-util.js')

Page({
  data: {
    userInfo: null,
    isVerified: false,
    ratingDisplay: '-',
    fullStars: 0,
    showRules: false,
    avatarLetter: '用',
    avatarColor: '#0EA5E9',
    starLevel: 1,
    starPoints: 0,
    starProgress: 0,
    starColor: '#AAAAAA',
    starLevelClass: 'star-1',
    rankTier: 'bronze',
    rankIcon: '🛡',
    rankName: '青铜',
    isAdmin: false,
    isManager: false,
    unreadNotifyCount: 0,
    showServiceMask: false,
    showStarDetail: false,
    ratingCount: 0,
    nextStarPoints: 50
  },

  /**
   * 根据昵称生成头像背景颜色
   */
  getAvatarColor: function (name) {
    var colors = ['#0EA5E9', '#8B5CF6', '#F59E0B', '#10B981', '#EF4444', '#EC4899', '#6366F1', '#14B8A6']
    var hash = 0
    for (var i = 0; i < name.length; i++) {
      hash = name.charCodeAt(i) + ((hash << 5) - hash)
    }
    return colors[Math.abs(hash) % colors.length]
  },

  formatRatingDisplay: function(rating) {
    if (!rating || rating === 0) return '-'
    // 确保显示为一位小数
    var num = parseFloat(rating)
    if (isNaN(num)) return '-'
    return num.toFixed(1)
  },

  /**
   * 根据用户数据计算星级信息
   */
  calcStarLevel: function(data) {
    // 创始人特殊段位（最高）
    if (data.isAdmin) {
      return {
        starLevel: 99,
        starPoints: 999,
        starProgress: 100,
        starColor: '#FF0000',
        starLevelClass: 'star-admin',
        rankTier: 'admin',
        rankIcon: '👑',
        rankName: '创始人'
      }
    }
    // 管理员段位（仅次于创始人）
    if (data.isManager) {
      return {
        starLevel: 98,
        starPoints: 999,
        starProgress: 100,
        starColor: '#E8E8F0',
        starLevelClass: 'star-manager',
        rankTier: 'manager',
        rankIcon: '🌙',
        rankName: '管理员'
      }
    }
    var starPoints = data.starPoints || 0
    var starLevel = Math.min(10, Math.floor(starPoints / 50) + 1)
    var starProgress = starLevel < 10 ? ((starPoints % 50) / 50 * 100) : 100
    // 十级称号体系：从新手到传说
    var colors = ['#9CA3AF', '#6B7280', '#3B82F6', '#EF4444', '#F59E0B', '#10B981', '#8B5CF6', '#EC4899', '#0EA5E9', '#FFD700']
    var tiers = [
      { name: '萌新', tier: 'newbie', icon: '🌱' },
      { name: '学徒', tier: 'apprentice', icon: '📚' },
      { name: '帮客', tier: 'helper', icon: '💪' },
      { name: '精英帮客', tier: 'elite', icon: '⭐' },
      { name: '金牌帮客', tier: 'gold', icon: '🥇' },
      { name: '大师', tier: 'master', icon: '💎' },
      { name: '宗师', tier: 'grandmaster', icon: '👑' },
      { name: '传奇', tier: 'legend', icon: '✨' },
      { name: '神话', tier: 'myth', icon: '🌟' },
      { name: '至尊', tier: 'supreme', icon: '🏆' }
    ]
    var tierInfo = tiers[starLevel - 1] || tiers[0]
    return {
      starLevel: starLevel,
      starPoints: starPoints,
      starProgress: starProgress,
      starColor: colors[starLevel - 1],
      starLevelClass: 'star-' + starLevel,
      rankTier: tierInfo.tier,
      rankIcon: tierInfo.icon,
      rankName: tierInfo.name
    }
  },

  onShow: function() {
    if (typeof this.getTabBar === 'function' && this.getTabBar()) {
      this.getTabBar().setData({ selected: 4 })
    }
    var that = this

    // 直接用全局数据刷新页面，不调云函数（避免闪烁和重复创建用户）
    var userInfo = app.globalData && app.globalData.userInfo
      ? app.globalData.userInfo
      : null

    // 如果全局没数据，尝试从缓存读取
    if (!userInfo || !userInfo._id) {
      try {
        var cached = wx.getStorageSync('userInfo')
        if (cached) userInfo = JSON.parse(cached)
      } catch (e) {}
    }

    that.setData({
      userInfo: userInfo,
      ratingDisplay: that.formatRatingDisplay(userInfo ? userInfo.rating : 0),
      ratingCount: (userInfo && userInfo.ratingCount) || 0,
      fullStars: Math.floor(userInfo ? (userInfo.rating || 0) : 0),
      isVerified: false,
      isAdmin: !!(userInfo && userInfo.isAdmin),
      isManager: !!(userInfo && userInfo.isManager),
      avatarLetter: (userInfo && userInfo.nickName) ? userInfo.nickName[0] : '用',
      avatarColor: that.getAvatarColor((userInfo && userInfo.nickName) || '用户')
    })
    if (userInfo) {
      var starInfo = that.calcStarLevel(userInfo)
      var nextPoints = starInfo.starLevel < 10 ? 50 - (starInfo.starPoints % 50) : 0
      that.setData({ ...starInfo, nextStarPoints: nextPoints })
    }

    // 加载未读通知数
    that.loadUnreadNotifyCount()
    // 刷新未读消息红点
    commonUtil.loadGlobalUnreadMsg()

    // 如果有 _id 但没有 isAdmin 字段（刚在数据库手动添加），从云端刷新一次
    if (userInfo && userInfo._id && userInfo.isAdmin === undefined) {
      wx.cloud.callFunction({
        name: 'login',
        data: { action: 'autoCreate', _id: userInfo._id },
        success: function(res) {
          if (res.result && res.result.code === 0) {
            var data = res.result.data
            app.globalData.userInfo = data
            wx.setStorageSync('userInfo', JSON.stringify(data))
            that.setData({
              userInfo: data,
              isAdmin: !!(data && data.isAdmin),
              avatarLetter: data.nickName ? data.nickName[0] : '用',
              avatarColor: that.getAvatarColor(data.nickName || '用户')
            })
            var starInfo = that.calcStarLevel(data)
            that.setData(starInfo)
          }
        }
      })
    }
  },

  goEditProfile: function() {
    wx.navigateTo({
      url: '/pages/edit-profile/edit-profile'
    })
  },

  showRulesFromProfile: function() {
    this.setData({ showRules: true })
  },

  goMyRating: function() {
    this.setData({ showStarDetail: true })
  },

  closeStarDetail: function() {
    this.setData({ showStarDetail: false })
  },

  closeRules: function() {
    this.setData({ showRules: false })
  },

  goMyPublish: function() {
    app.globalData.ordersViewType = 'mine'
    wx.switchTab({
      url: '/pages/orders/orders'
    })
  },

  goMyAccept: function() {
    app.globalData.ordersViewType = 'accept'
    wx.switchTab({
      url: '/pages/orders/orders'
    })
  },

  goCredit: function() {
    var userInfo = this.data.userInfo
    var creditScore = (userInfo && userInfo.creditScore) || 100
    wx.showModal({
      title: '我的信用分',
      content: '当前信用分：' + creditScore + '分\n\n信用分说明：\n- 初始信用分100分\n- 每次被投诉扣减10分\n- 信用分过低可能影响接单权限',
      showCancel: false,
      confirmText: '知道了'
    })
  },

  goComplaint: function() {
    wx.navigateTo({ url: '/pages/complaint/complaint' })
  },

  loadUnreadNotifyCount: function() {
    var that = this
    try {
      wx.cloud.callFunction({
        name: 'login',
        data: { action: 'getUnreadNotifyCount', userInfo: app.globalData.userInfo || {} },
        success: function(res) {
          if (res.result && res.result.code === 0) {
            var count = res.result.data || 0
            that.setData({ unreadNotifyCount: count })
            commonUtil.updateTabBarBadge({ notifyCount: count })
          }
        },
        fail: function() {}
      })
    } catch(e) {}
  },

  goNotifications: function() {
    wx.navigateTo({ url: '/pages/notifications/notifications' })
  },

  goAbout: function() {
    wx.showModal({
      title: '关于帮到位',
      content: '帮到位 - 校园万能互助平台\n\n版本：v1.0.0\n纯公益项目，零抽成服务同学',
      showCancel: false,
      confirmText: '知道了'
    })
  },

  openService: function() {
    this.setData({ showServiceMask: true })
  },

  closeService: function() {
    this.setData({ showServiceMask: false })
  },

  copyWechat: function() {
    wx.setClipboardData({
      data: 'Syyf2025129',
      success: function() {
        wx.showToast({ title: '已复制', icon: 'success' })
      }
    })
  },

  goFeedback: function() {
    wx.navigateTo({
      url: '/pages/feedback/feedback'
    })
  },

  goAdmin: function() {
    wx.navigateTo({ url: '/pages/admin/admin' })
  },

  /**
   * 清除缓存
   */
  onClearCache: function() {
    wx.showModal({
      title: '清除缓存',
      content: '确定要清除本地缓存吗？用户数据不会丢失，重新打开小程序会自动恢复',
      success: function(res) {
        if (res.confirm) {
          wx.clearStorageSync()
          wx.showToast({ title: '缓存已清除', icon: 'success' })
          // 重新调login获取数据
          setTimeout(function() {
            wx.cloud.callFunction({
              name: 'login',
              data: { action: 'autoCreate' },
              success: function(loginRes) {
                if (loginRes.result && loginRes.result.code === 0) {
                  var data = loginRes.result.data
                  app.globalData.userInfo = data
                  wx.setStorageSync('userInfo', JSON.stringify(data))
                  if (data._openid) {
                    wx.setStorageSync('myOpenId', data._openid)
                  }
                }
              }
            })
          }, 500)
        }
      }
    })
  }
})
