/**
 * 首页逻辑 - 帮到位校园互助小程序
 * 数据来源：云数据库直读紧急订单列表
 */

var app = getApp()
var commonUtil = require('../../utils/common-util.js')

Page({
  data: {
    urgentOrders: [],
    stats: {
      totalHelp: 0,
      totalHelpText: '0',
      activeUsers: 0,
      activeUsersText: '0',
      satisfaction: 0,
      satisfactionText: '0%'
    },
    statsLoading: true,
    // 加载状态
    loading: true,
    loadError: false,
    // 当前分类
    category: 'all',
    // 首次使用守则弹窗
    showRules: false,
    // 首次注册弹窗
    showRegister: false,
    registerPhone: '',
    // 滚动公告
    activeNotices: [],
    showAd: true
  },

  onLoad: function () {
    wx.setStorageSync('lastIndexLoad', Date.now())
    this.loadUrgentOrders()
    this.loadStats()
    this.loadNotices()
  },

  onShow: function () {
    var that = this
    if (typeof this.getTabBar === 'function' && this.getTabBar()) {
      this.getTabBar().setData({ selected: 0 })
    }
    var now = Date.now()
    var lastLoad = wx.getStorageSync('lastIndexLoad') || 0
    if (now - lastLoad > 5000 && !this._loadingOrders) {
      wx.setStorageSync('lastIndexLoad', now)
      that.loadUrgentOrders()
      that.loadStats()
    }
    // 刷新未读消息红点
    commonUtil.loadGlobalUnreadMsg()
    // 检查是否需要弹出使用守则
    var agreedRules = wx.getStorageSync('agreedRules')
    if (!agreedRules) {
      that.setData({ showRules: true })
    }
    // 检查是否已注册（有手机号）
    var userInfo = app.globalData.userInfo
    if (!userInfo || !userInfo.phone || !userInfo._id) {
      that.setData({ showRegister: true })
    }
  },

  /**
   * 切换分类
   */
  switchCategory: function (e) {
    var cat = e.currentTarget.dataset.cat
    if (cat === this.data.category) return
    this.setData({ category: cat })
    this.loadUrgentOrders()
  },

  /**
   * 加载附近需求订单（pending状态，带缓存）
   */
  loadUrgentOrders: function (callback) {
    var that = this
    if (this._loadingOrders) {
      if (callback) callback()
      return
    }
    this._loadingOrders = true

    // 先读缓存，快速展示
    var cacheKey = 'urgentOrders_' + that.data.category
    var cachedOrders = commonUtil.Cache.get(cacheKey)
    if (cachedOrders && cachedOrders.length > 0) {
      that.setData({ urgentOrders: cachedOrders, loading: false })
    }

    wx.cloud.callFunction({
      name: 'getOrders',
      data: {
        viewType: 'all',
        status: 'pending',
        category: that.data.category,
        page: 1,
        pageSize: 2
      },
      success: function (res) {
        var result = res.result
        var orders = []
        if (result && result.code === 0) {
          orders = result.data.orders || []
          var now = Date.now()
          var cachedOpenId = wx.getStorageSync('myOpenId') || ''
          var cachedUserInfo = app.globalData && app.globalData.userInfo
          var myOpenid = cachedOpenId || (cachedUserInfo && cachedUserInfo._openid) || ''
          for (var i = 0; i < orders.length; i++) {
            orders[i].time = commonUtil.formatTime(orders[i].createTime)
            var createTime = new Date(orders[i].createTime).getTime()
            if (now - createTime > 24 * 60 * 60 * 1000) {
              orders[i].isExpired = true
            }
            if (!orders[i].publisherStarLevel) {
              orders[i].publisherStarLevel = 5
            }
            if (myOpenid) {
              orders[i].isMine = orders[i].publisherId === myOpenid
            }
          }
          that.setData({ urgentOrders: orders, loading: false })
          // 写入缓存，3分钟有效期
          commonUtil.Cache.set(cacheKey, orders, 3)
          // 异步转换图片URL（不阻塞UI），添加竞态保护
          that._imgLoadVersion = (that._imgLoadVersion || 0) + 1
          var ver = that._imgLoadVersion
          commonUtil.convertOrderImages(orders).then(function() {
            if (ver !== that._imgLoadVersion) return
            that.setData({ urgentOrders: orders })
          })
        } else {
          that.setData({ loading: false })
        }
        if (callback) callback()
      },
      fail: function (err) {
        console.error('[帮到位] 加载附近需求失败', err)
        that.setData({ loading: false, loadError: true })
        if (callback) callback()
      },
      complete: function () {
        that._loadingOrders = false
      }
    })
  },

  /**
   * 加载平台统计数据（带缓存）
   */
  loadStats: function (callback) {
    var that = this
    // 先读缓存
    var cachedStats = commonUtil.Cache.get('platformStats')
    if (cachedStats) {
      that.setData({ statsLoading: false })
      that.animateNumber('totalHelp', cachedStats.totalHelp, function (val) {
        return val > 999 ? (val / 1000).toFixed(1) + 'k+' : val + '+'
      })
      that.animateNumber('activeUsers', cachedStats.activeUsers, function (val) {
        return val.toString()
      })
      that.animateNumber('satisfaction', cachedStats.satisfaction, function (val) {
        return val.toFixed(1) + '%'
      })
    }

    wx.cloud.callFunction({
      name: 'getPlatformStats',
      success: function (res) {
        var result = res.result
        if (result.code === 0) {
          var data = result.data
          that.setData({ statsLoading: false })
          that.animateNumber('totalHelp', data.totalHelp, function (val) {
            return val > 999 ? (val / 1000).toFixed(1) + 'k+' : val + '+'
          })
          that.animateNumber('activeUsers', data.activeUsers, function (val) {
            return val.toString()
          })
          that.animateNumber('satisfaction', data.satisfaction, function (val) {
            return val.toFixed(1) + '%'
          })
          // 写入缓存，5分钟有效期
          commonUtil.Cache.set('platformStats', data, 5)
          if (callback) callback()
        } else {
          that.setData({ statsLoading: false })
          if (callback) callback()
        }
      },
      fail: function () {
        that.setData({ statsLoading: false })
        if (callback) callback()
      }
    })
  },

  /**
   * 数字滚动动画
   * @param {String} key - stats 中的字段名
   * @param {Number} targetValue - 目标值
   * @param {Function} formatter - 格式化函数
   */
  animateNumber: function (key, targetValue, formatter) {
    var that = this
    var duration = 1500
    var startTime = null
    var startValue = 0

    // 动画版本号，启动新动画时取消旧动画
    if (!that._animVersions) that._animVersions = {}
    that._animVersions[key] = (that._animVersions[key] || 0) + 1
    var ver = that._animVersions[key]

    function step(timestamp) {
      if (ver !== that._animVersions[key]) return
      if (!startTime) startTime = timestamp
      var progress = Math.min((timestamp - startTime) / duration, 1)
      var easeProgress = 1 - Math.pow(1 - progress, 3)
      var currentValue = Math.round(startValue + (targetValue - startValue) * easeProgress)

      var stats = that.data.stats
      stats[key] = currentValue
      stats[key + 'Text'] = formatter(currentValue)
      that.setData({ stats: stats })

      if (progress < 1) {
        wx.nextTick(function () { step(Date.now()) })
      }
    }
    step(Date.now())
  },

  goAllOrders: function () {
    app.globalData.ordersViewType = 'all'
    app.globalData.activeTab = 'pending'
    app.globalData.searchKeyword = ''
    wx.switchTab({ url: '/pages/orders/orders' })
  },

  goPublish: function () {
    wx.switchTab({ url: '/pages/publish/publish' })
  },

  goAccept: function () {
    app.globalData.ordersViewType = 'all'
    wx.switchTab({ url: '/pages/orders/orders' })
  },

  goOrders: function () {
    wx.switchTab({ url: '/pages/orders/orders' })
  },

  goProfile: function () {
    wx.switchTab({ url: '/pages/profile/profile' })
  },

  goDetail: function (e) {
    var id = e.currentTarget.dataset.id
    if (id) {
      wx.navigateTo({
        url: '/pages/order-detail/order-detail?id=' + id
      })
    }
  },

  previewImage: function (e) {
    var images = e.currentTarget.dataset.images || []
    if (images.length > 0) {
      wx.previewImage({
        current: images[0],
        urls: images
      })
    }
  },

  /**
   * 下拉刷新
   */
  onPullDownRefresh: function () {
    var that = this
    var done = 0
    var total = 3
    function checkDone() {
      done++
      if (done >= total) wx.stopPullDownRefresh()
    }
    // 清除缓存，强制刷新
    commonUtil.Cache.remove('urgentOrders_' + that.data.category)
    commonUtil.Cache.remove('platformStats')
    that.setData({ loading: true })
    that.loadUrgentOrders(function() { checkDone() })
    that.loadStats(function() { checkDone() })
    that.loadNotices(function() { checkDone() })
  },

  /**
   * 加载有效公告（未过期的）
   */
  loadNotices: function (callback) {
    var that = this
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'getNotices', school: (app.globalData.userInfo && app.globalData.userInfo.school) || '' },
      success: function (res) {
        if (res.result && res.result.code === 0) {
          that.setData({ activeNotices: res.result.data || [] })
          if (callback) callback()
        }
      },
      fail: function () { if (callback) callback() }
    })
  },

  /**
   * 广告加载失败
   */
  onAdError: function (e) {
    this.setData({ showAd: false })
  },
  onAdLoad: function () {},

  /**
   * 同意使用守则
   */
  agreeRules: function () {
    wx.setStorageSync('agreedRules', true)
    this.setData({ showRules: false })
  },

  /**
   * 关闭使用守则弹窗（不允许关闭，必须同意）
   */
  closeRules: function () {
    wx.showToast({ title: '请先同意使用守则', icon: 'none' })
  },

  /**
   * 注册弹窗 - 手机号输入
   */
  bindRegisterPhone: function (e) {
    this.setData({ registerPhone: e.detail.value.replace(/\D/g, '') })
  },

  /**
   * 注册弹窗 - 提交注册
   */
  submitRegister: function () {
    var that = this
    var phone = that.data.registerPhone.trim()
    if (phone.length !== 11) {
      wx.showToast({ title: '请输入正确的11位手机号', icon: 'none' })
      return
    }
    wx.showLoading({ title: '注册中' })
    wx.cloud.callFunction({
      name: 'login',
      data: {
        action: 'registerWithPhone',
        phone: phone,
        _id: (app.globalData.userInfo && app.globalData.userInfo._id) || ''
      },
      success: function (res) {
        wx.hideLoading()
        if (res.result && res.result.code === 0) {
          var data = res.result.data
          app.globalData.userInfo = data
          wx.setStorageSync('userInfo', JSON.stringify(data))
          if (data._openid) wx.setStorageSync('myOpenId', data._openid)
          that.setData({ showRegister: false, registerPhone: '' })
          wx.showToast({ title: '注册成功', icon: 'success' })
          // 刷新首页数据
          that.loadUrgentOrders()
        } else {
          wx.showToast({ title: (res.result && res.result.msg) || '注册失败', icon: 'none' })
        }
      },
      fail: function () {
        wx.hideLoading()
        wx.showToast({ title: '网络错误，请重试', icon: 'none' })
      }
    })
  }
})
