/**
 * 订单列表页逻辑
 * 功能：tab切换、视图切换（全部/我的发布/我的接单）、订单加载、分页、接单、确认送达等操作
 * 数据来源：云函数 getOrders / acceptOrder / completeOrder
 */

var app = getApp()
var commonUtil = require('../../utils/common-util.js')

Page({
  data: {
    // 当前激活的tab：all/pending/accepted/paid/cancelled
    activeTab: 'pending',
    // 视图类型：all/mine/accept，默认全部
    viewType: 'all',
    // 订单列表数据
    orders: [],
    // 当前页码
    page: 1,
    // 是否还有更多数据
    hasMore: true,
    // 是否正在加载
    loading: false,
    // 每页数量
    pageSize: 10,
    // 筛选：楼栋
    filterBuilding: '',
    // 筛选：楼层
    filterFloor: '',
    // 是否显示筛选栏
    showFilter: false,
    // 当前分类
    category: 'all',
    // 排序类型：newest/price_asc/price_desc
    sortType: 'newest',
    // 搜索关键词
    searchKeyword: '',
    // 我的发布未读数（小红点）
    mineUnreadCount: 0,
    // 我的接单未读数（数字徽章）
    acceptUnreadCount: 0,
    // 我的发布新接单数（红点提示）
    newAcceptedCount: 0,
  },

  /**
   * 页面加载
   * @param {Object} options - 页面参数
   *   type: 可传入tab类型（pending/accepted/completed）
   *   view: 可传入视图类型（mine/accept）
   */
  onLoad: function (options) {
    // 如果传入了type参数，切换到对应tab
    if (options && options.type) {
      this.setData({ activeTab: options.type })
    }
    // 如果传入了view参数，切换到对应视图（我的发布/我的接单）
    if (options && options.view) {
      this.setData({ viewType: options.view })
    }
  },

  /**
   * 页面显示时加载订单
   * 检查全局变量 ordersViewType（从profile页面switchTab传递）
   */
  onShow: function () {
    if (typeof this.getTabBar === 'function' && this.getTabBar()) {
      this.getTabBar().setData({ selected: 1 })
    }
    // 从全局变量读取视图类型（switchTab无法传参，通过globalData传递）
    var viewType = app.globalData.ordersViewType
    var activeTab = app.globalData.activeTab
    var searchKeyword = app.globalData.searchKeyword

    var changed = false
    if (viewType && viewType !== this.data.viewType) {
      var newActiveTab
      if (viewType === 'all') {
        newActiveTab = 'pending'
      } else {
        newActiveTab = activeTab || 'all'
      }
      this.setData({ viewType: viewType, activeTab: newActiveTab, page: 1, orders: [] })
      changed = true
    } else if (activeTab && activeTab !== this.data.activeTab) {
      this.setData({ activeTab: activeTab, page: 1, orders: [] })
      changed = true
    }
    if (searchKeyword) {
      this.setData({ filterBuilding: searchKeyword, page: 1, orders: [], showFilter: true })
      changed = true
    }
    // 清除全局变量，避免下次onShow重复切换
    app.globalData.ordersViewType = ''
    app.globalData.activeTab = ''
    app.globalData.searchKeyword = ''
    // 节流：3秒内不重复加载（除非视图有变化）
    var now = Date.now()
    var cacheKey = 'orders_' + this.data.viewType + '_' + this.data.activeTab + '_' + this.data.category + '_' + (this.data.searchKeyword || '')
    var cachedOrders = commonUtil.Cache.get(cacheKey)
    
    if (changed || now - (this.data.lastLoadTime || 0) > 3000 || !cachedOrders) {
      this.setData({ lastLoadTime: now })
      this.loadOrders()
    } else {
      var viewedAccepted = wx.getStorageSync('viewedAcceptedOrders') || []
      for (var c = 0; c < cachedOrders.length; c++) {
        if (cachedOrders[c].isNewAccepted && viewedAccepted.indexOf(cachedOrders[c]._id) !== -1) {
          cachedOrders[c].isNewAccepted = false
        }
      }
      this.setData({ orders: cachedOrders })
      this.updateNewAcceptedCount(cachedOrders)
      this.updateMarksFromViewed()
    }
    // 每次显示都刷新未读统计（独立于列表加载）
    // 只要进入接单广场Tab，就更新最后查看时间，红点消失
    wx.setStorageSync('lastViewedOrdersTime', Date.now())
    commonUtil.updateTabBarBadge({ msgCount: 0 })
    
    // 启动定时刷新（每30秒刷新一次订单状态）
    this.startAutoRefresh()
  },

  onHide: function () {
    // 停止定时刷新
    this.stopAutoRefresh()
  },

  onUnload: function () {
    this.stopAutoRefresh()
  },

  startAutoRefresh: function () {
    if (this._refreshTimer) return
    var that = this
    this._refreshTimer = setInterval(function () {
      that.loadGlobalUnreadCounts()
    }, 60000)
  },

  stopAutoRefresh: function () {
    if (this._refreshTimer) {
      clearInterval(this._refreshTimer)
      this._refreshTimer = null
    }
  },

  updateMarksFromViewed: function () {
    var viewedAccepted = wx.getStorageSync('viewedAcceptedOrders') || []
    var orders = this.data.orders
    var changed = false
    for (var i = 0; i < orders.length; i++) {
      if (orders[i].isNewAccepted && viewedAccepted.indexOf(orders[i]._id) !== -1) {
        orders[i].isNewAccepted = false
        changed = true
      }
    }
    if (changed) {
      this.setData({ orders: orders })
      this.updateNewAcceptedCount(orders)
    }
  },

  markAllAcceptedViewed: function () {
    var that = this
    var myOpenId = wx.getStorageSync('myOpenId') || ''
    if (!myOpenId) {
      var userInfo = app.globalData.userInfo
      myOpenId = userInfo && userInfo._openid ? userInfo._openid : ''
    }
    if (!myOpenId) {
      var cachedUser = wx.getStorageSync('userInfo') || ''
      try { cachedUser = JSON.parse(cachedUser) } catch(e) { cachedUser = {} }
      myOpenId = cachedUser._openid || ''
    }
    if (!myOpenId) {
      that.setData({ newAcceptedCount: 0 })
      commonUtil.updateTabBarBadge({ msgCount: 0 })
      return
    }

    var db = wx.cloud.database()
    db.collection('orders').where({
      publisherId: myOpenId,
      status: 'accepted'
    }).field({ _id: true }).get({
      success: function (res) {
        var orders = res.data || []
        var viewed = wx.getStorageSync('viewedAcceptedOrders') || []
        var changed = false
        for (var i = 0; i < orders.length; i++) {
          if (viewed.indexOf(orders[i]._id) === -1) {
            viewed.push(orders[i]._id)
            changed = true
          }
        }
        if (changed) {
          wx.setStorageSync('viewedAcceptedOrders', viewed)
        }
        that.setData({ newAcceptedCount: 0 })
        commonUtil.updateTabBarBadge({ msgCount: 0 })

        var currentOrders = that.data.orders
        var orderChanged = false
        for (var j = 0; j < currentOrders.length; j++) {
          if (currentOrders[j].isNewAccepted) {
            currentOrders[j].isNewAccepted = false
            orderChanged = true
          }
        }
        if (orderChanged) {
          that.setData({ orders: currentOrders })
        }
      },
      fail: function () {
        that.setData({ newAcceptedCount: 0 })
        commonUtil.updateTabBarBadge({ msgCount: 0 })
      }
    })
  },

  /**
   * 下拉刷新
   */
  onPullDownRefresh: function () {
    var that = this
    // 清除当前缓存，强制刷新
    var cacheKey = 'orders_' + that.data.viewType + '_' + that.data.activeTab + '_' + that.data.category + '_' + (that.data.searchKeyword || '')
    commonUtil.Cache.remove(cacheKey)
    // 重置分页状态
    that.setData({
      page: 1,
      hasMore: true,
      orders: []
    })
    that.loadOrders(function () {
      wx.stopPullDownRefresh()
    })
  },

  /**
   * 上拉加载更多
   */
  onReachBottom: function () {
    if (this.data.hasMore && !this.data.loading) {
      this.loadOrders()
    }
  },

  /**
   * 切换状态tab（待接单/进行中/已完成）
   * @param {Object} e - 事件对象，获取data-tab值
   */
  switchTab: function (e) {
    var tab = e.currentTarget.dataset.tab
    if (tab === this.data.activeTab) return

    this.setData({
      activeTab: tab,
      page: 1,
      hasMore: true,
      orders: []
    })
    this.loadOrders()
  },

  /**
   * 切换分类
   */
  switchCategory: function (e) {
    var cat = e.currentTarget.dataset.cat
    if (cat === this.data.category) return
    this.setData({
      category: cat,
      page: 1,
      hasMore: true,
      orders: []
    })
    this.loadOrders()
  },

  /**
   * 切换视图类型（全部订单/我的发布/我的接单）
   * @param {Object} e - 事件对象，获取data-view值
   */
  switchView: function (e) {
    var viewType = e.currentTarget.dataset.view
    if (viewType === this.data.viewType) return

    var activeTab
    if (viewType === 'all') {
      activeTab = 'pending'
    } else {
      activeTab = 'all'
    }

    var updateData = {
      viewType: viewType,
      activeTab: activeTab,
      page: 1,
      hasMore: true,
      orders: [],
      searchKeyword: ''
    }

    if (viewType === 'mine') {
      updateData.newAcceptedCount = 0
      wx.setStorageSync('lastViewedOrdersTime', Date.now())
      commonUtil.updateTabBarBadge({ msgCount: 0 })
    }

    this.setData(updateData)
    this.loadOrders()
  },

  /**
   * 搜索输入
   */
  onSearchInput: function(e) {
    this.setData({ searchKeyword: e.detail.value })
  },

  /**
   * 执行搜索
   */
  doSearch: function() {
    var that = this
    that.setData({ page: 1, orders: [], hasMore: true })
    that.loadOrders()
  },

  onFilterCategory: function(e) {
    var category = e.currentTarget.dataset.category
    var that = this
    that.setData({ category: category, page: 1, orders: [], hasMore: true })
    that.loadOrders()
  },

  onFilterSort: function(e) {
    var sortType = e.currentTarget.dataset.sort
    var that = this
    that.setData({ sortType: sortType, page: 1, orders: [], hasMore: true })
    that.loadOrders()
  },

  /**
   * 加载订单列表（带缓存，第1页缓存3分钟）
   * 调用云函数 getOrders 获取订单数据
   * @param {Function} callback - 加载完成后的回调
   */
  loadOrders: function (callback) {
    var that = this
    if (that.data.loading) {
      if (callback) callback()
      return
    }

    that.setData({ loading: true })

    var page = that.data.page
    var cacheKey = 'orders_' + that.data.viewType + '_' + that.data.activeTab + '_' + that.data.category + '_' + (that.data.searchKeyword || '')

    // 第1页先读缓存，快速展示
    if (page === 1) {
      var cachedOrders = commonUtil.Cache.get(cacheKey)
      if (cachedOrders && cachedOrders.length > 0) {
        // 更新缓存中订单的 isNewAccepted 标记（根据已查看列表）
        var viewedAccepted = wx.getStorageSync('viewedAcceptedOrders') || []
        for (var c = 0; c < cachedOrders.length; c++) {
          if (cachedOrders[c].isNewAccepted && viewedAccepted.indexOf(cachedOrders[c]._id) !== -1) {
            cachedOrders[c].isNewAccepted = false
          }
        }
        that.setData({ orders: cachedOrders, loading: false })
        that.updateNewAcceptedCount(cachedOrders)
      }
    }

    wx.cloud.callFunction({
      name: 'getOrders',
      data: {
        viewType: that.data.viewType,
        status: that.data.activeTab,
        category: that.data.category,
        page: page,
        pageSize: that.data.pageSize,
        keyword: that.data.searchKeyword || '',
        sortBy: that.data.sortType
      },
      success: function (res) {
        var result = res.result
        if (result && result.code === 0) {
          var newOrders = result.data.orders || []

          // 前端重新验证 isMine，避免云函数缓存或身份判断错误
          var cachedOpenId = wx.getStorageSync('myOpenId') || ''
          var cachedUserInfo = app.globalData && app.globalData.userInfo
          var myOpenid = cachedOpenId || (cachedUserInfo && cachedUserInfo._openid) || ''

          // 读取已查看的接单订单列表，用于标记"新接单"
          var lastViewedTime = wx.getStorageSync('lastViewedOrdersTime') || 0

          for (var i = 0; i < newOrders.length; i++) {
            newOrders[i].createTimeText = commonUtil.formatTime(newOrders[i].createTime)
            if (myOpenid) {
              newOrders[i].isMine = newOrders[i].publisherId === myOpenid
            }
            // 标记"新接单"：我的发布 + accepted状态 + 接单时间晚于最后查看时间
            newOrders[i].isNewAccepted = false
            if (newOrders[i].isMine && newOrders[i].status === 'accepted' && newOrders[i].acceptTime) {
              var acceptTime = new Date(newOrders[i].acceptTime).getTime()
              if (acceptTime > lastViewedTime) {
                newOrders[i].isNewAccepted = true
              }
            }
          }

          var orders = page === 1 ? newOrders : that.data.orders.concat(newOrders)
          that.setData({
            orders: orders,
            loading: false,
            hasMore: result.data.hasMore,
            page: page + 1
          })
          // 更新"我的发布"新接单数量
          that.updateNewAcceptedCount(orders)
          if (page === 1) {
            setTimeout(function() {
              that.loadUnreadCounts(orders)
            }, 500)
            commonUtil.Cache.set(cacheKey, orders, 3)
            // 异步转换图片URL（不阻塞UI），添加竞态保护
            that._imgLoadVersion = (that._imgLoadVersion || 0) + 1
            var ver = that._imgLoadVersion
            commonUtil.convertOrderImages(orders).then(function() {
              if (ver !== that._imgLoadVersion) return
              that.setData({ orders: orders })
            })
          }
        } else {
          console.error('[帮到位] getOrders返回错误', result)
          that.setData({ loading: false })
        }
        if (callback) callback()
      },
      fail: function (err) {
        console.error('[帮到位] getOrders云函数调用失败', err)
        that.setData({ loading: false })
        if (callback) callback()
      }
    })
  },

  /**
   * 获取订单状态对应的文字描述
   * @param {String} status - 订单状态
   * @returns {String} 状态文字
   */
  getStatusText: function (status) {
    var textMap = {
      'pending': '待接单',
      'accepted': '进行中',
      'delivered': '待付款',
      'paid': '已完成'
    }
    return textMap[status] || '未知状态'
  },

  /**
   * 接单操作
   * 调用云函数 acceptOrder
   * @param {Object} e - 事件对象，获取订单id
   */
  onAccept: function (e) {
    var that = this

    // 检查手机号
    var cachedUser = wx.getStorageSync('userInfo')
    try { cachedUser = JSON.parse(cachedUser) } catch(e) { cachedUser = {} }
    if (!cachedUser.phone || cachedUser.phone.length !== 11) {
      wx.showModal({
        title: '需要填写手机号',
        content: '使用此功能需要先填写手机号码',
        confirmText: '去填写',
        success: function (modalRes) {
          if (modalRes.confirm) {
            wx.navigateTo({ url: '/pages/edit-profile/edit-profile' })
          }
        }
      })
      return
    }

    var id = e.currentTarget.dataset.id
    var order = that.data.orders.find(function (o) { return o._id === id })
    if (!order) {
      wx.showToast({ title: '订单不存在或已刷新', icon: 'none' })
      return
    }

    wx.showModal({
      title: '确认接单',
      content: '确定要接下这个订单吗？\n' + order.building + ' ' + order.room + '，报酬¥' + order.price,
      confirmColor: '#0EA5E9',
      success: function (res) {
        if (res.confirm) {
          // 调用云函数接单
          wx.cloud.callFunction({
            name: 'acceptOrder',
            data: {
              orderId: id
            },
            success: function (res) {
              var result = res.result
              if (result.code === 0) {
                wx.showToast({
                  title: '接单成功',
                  icon: 'success'
                })
                // 从列表中移除该订单（因为状态改变了）
                var orders = that.data.orders.filter(function (o) { return o._id !== id })
                that.setData({ orders: orders })
              } else {
                wx.showToast({
                  title: result.msg || '接单失败',
                  icon: 'none'
                })
              }
            },
            fail: function (err) {
              console.error('[帮到位] acceptOrder云函数失败', err)
              wx.showToast({
                title: '接单失败，请重试',
                icon: 'none'
              })
            }
          })
        }
      }
    })
  },

  /**
   * 联系下单人
   * @param {Object} e - 事件对象
   */
  onContact: function (e) {
    var id = e.currentTarget.dataset.id
    var order = this.data.orders.find(function (o) { return o._id === id })
    if (!order) {
      wx.showToast({ title: '订单不存在或已刷新', icon: 'none' })
      return
    }
    var phone = order.publisherPhone || '未提供'
    if (phone === '未提供') {
      wx.showToast({ title: '对方未提供联系方式', icon: 'none' })
      return
    }
    wx.showModal({
      title: '联系方式',
      content: '电话号码：' + phone + '\n\n建议通过电话沟通协商细节和支付方式',
      confirmText: '拨打电话',
      cancelText: '复制号码',
      success: function (res) {
        if (res.confirm) {
          wx.makePhoneCall({ phoneNumber: phone })
        } else if (res.cancel) {
          wx.setClipboardData({
            data: phone,
            success: function () {
              wx.showToast({ title: '已复制', icon: 'success' })
            }
          })
        }
      }
    })
  },

  /**
   * 确认送达操作
   * 调用云函数 completeOrder
   * @param {Object} e - 事件对象，获取订单id
   */
  onComplete: function (e) {
    var that = this
    var id = e.currentTarget.dataset.id

    wx.showModal({
      title: '确认送达',
      content: '确认已将水送到指定位置吗？',
      confirmColor: '#0EA5E9',
      success: function (res) {
        if (res.confirm) {
          // 调用云函数完成订单
          wx.cloud.callFunction({
            name: 'completeOrder',
            data: {
              orderId: id
            },
            success: function (res) {
              var result = res.result
              if (result.code === 0) {
                wx.showToast({
                  title: '已确认送达',
                  icon: 'success'
                })
                // 从列表中移除该订单
                var orders = that.data.orders.filter(function (o) { return o._id !== id })
                that.setData({ orders: orders })
              } else {
                wx.showToast({
                  title: result.msg || '操作失败',
                  icon: 'none'
                })
              }
            },
            fail: function (err) {
              console.error('[帮到位] completeOrder云函数失败', err)
              wx.showToast({
                title: '操作失败，请重试',
                icon: 'none'
              })
            }
          })
        }
      }
    })
  },

  /**
   * 评价操作
   * 跳转到订单详情页进行评价
   * @param {Object} e - 事件对象
   */
  onReview: function (e) {
    var id = e.currentTarget.dataset.id
    wx.navigateTo({
      url: '/pages/order-detail/order-detail?id=' + id
    })
  },

  /**
   * 跳转到聊天页面
   */
  goChat: function (e) {
    var id = e.currentTarget.dataset.id
    var order = this.data.orders.find(function (o) { return o._id === id })
    if (!order) {
      wx.showToast({ title: '订单不存在或已刷新', icon: 'none' })
      return
    }
    var orderNo = order ? (order.orderNo || '') : ''
    // 进入聊天前标记消息为已读
    wx.cloud.callFunction({
      name: 'markMessagesRead',
      data: { orderId: id },
      fail: function () {}
    })
    // 点击聊天也清除"新接单"标记
    if (order.status === 'accepted' && order.isMine) {
      var viewed = wx.getStorageSync('viewedAcceptedOrders') || []
      if (viewed.indexOf(id) === -1) {
        viewed.push(id)
        wx.setStorageSync('viewedAcceptedOrders', viewed)
      }
      var orders = this.data.orders
      for (var i = 0; i < orders.length; i++) {
        if (orders[i]._id === id) {
          orders[i].isNewAccepted = false
        }
      }
      var cacheKey = 'orders_' + this.data.viewType + '_' + this.data.activeTab + '_' + this.data.category + '_' + (this.data.searchKeyword || '')
      commonUtil.Cache.remove(cacheKey)
      var newAcceptedCount = this.data.newAcceptedCount > 0 ? this.data.newAcceptedCount - 1 : 0
      this.setData({ orders: orders, newAcceptedCount: newAcceptedCount })
      this.loadGlobalUnreadCounts()
    }
    wx.navigateTo({
      url: '/pages/chat/chat?id=' + id + '&orderNo=' + orderNo
    })
  },

  /**
   * 阻止事件冒泡（防止点击按钮时触发卡片点击跳转详情）
   */
  preventBubble: function () {
    // 空方法，仅用于阻止事件冒泡
  },

  /**
   * 跳转到订单详情页
   * @param {Object} e - 事件对象，获取订单id
   */
  goDetail: function (e) {
    var id = e.currentTarget.dataset.id
    var order = this.data.orders.find(function (o) { return o._id === id })
    // 进入订单详情时标记消息为已读（针对已接单/已送达状态）
    if (order && (order.status === 'accepted' || order.status === 'delivered')) {
      wx.cloud.callFunction({
        name: 'markMessagesRead',
        data: { orderId: id },
        fail: function () {}
      })
    }
    // 记录已查看的接单订单，用于清除"新接单"红色标记
    if (order && order.status === 'accepted' && order.isMine) {
      var viewed = wx.getStorageSync('viewedAcceptedOrders') || []
      if (viewed.indexOf(id) === -1) {
        viewed.push(id)
        wx.setStorageSync('viewedAcceptedOrders', viewed)
      }
      // 更新当前列表中的标记
      var orders = this.data.orders
      for (var i = 0; i < orders.length; i++) {
        if (orders[i]._id === id) {
          orders[i].isNewAccepted = false
        }
      }
      // 清除对应缓存，确保返回时重新加载数据
      var cacheKey = 'orders_' + this.data.viewType + '_' + this.data.activeTab + '_' + this.data.category + '_' + (this.data.searchKeyword || '')
      commonUtil.Cache.remove(cacheKey)
      // 立即更新界面
      var newAcceptedCount = this.data.newAcceptedCount > 0 ? this.data.newAcceptedCount - 1 : 0
      this.setData({ orders: orders, newAcceptedCount: newAcceptedCount })
      // 立即刷新未读统计（标记已读需要时间，这里先更新本地状态）
      this.loadGlobalUnreadCounts()
    }
    wx.navigateTo({
      url: '/pages/order-detail/order-detail?id=' + id
    })
  },

  /**
   * 预览商品大图
   */
  previewProductImage: function (e) {
    var images = e.currentTarget.dataset.images
    if (images && images.length > 0) {
      wx.previewImage({ urls: images, current: images[0] })
    }
  },

  /**
   * 更新"我的发布"新接单数量
   * @param {Array} ordersList - 订单列表
   */
  updateNewAcceptedCount: function (ordersList) {
    var count = 0
    for (var i = 0; i < ordersList.length; i++) {
      if (ordersList[i].isNewAccepted) count++
    }
    this.setData({ newAcceptedCount: count })
  },

  /**
   * 全局未读统计（不依赖当前列表，查询所有进行中的订单）
   * 统计：我的发布新接单数、我的接单未读数、底部TabBar红点
   */
  loadGlobalUnreadCounts: function() {
    var that = this
    var myOpenId = wx.getStorageSync('myOpenId') || ''
    if (!myOpenId) {
      var userInfo = app.globalData.userInfo
      myOpenId = userInfo && userInfo._openid ? userInfo._openid : ''
    }
    if (!myOpenId) {
      var cachedUser = wx.getStorageSync('userInfo') || ''
      try { cachedUser = JSON.parse(cachedUser) } catch(e) { cachedUser = {} }
      myOpenId = cachedUser._openid || ''
    }
    if (!myOpenId) return

    var db = wx.cloud.database()
    var _ = db.command

    var lastViewedTime = wx.getStorageSync('lastViewedOrdersTime') || 0
    var lastViewedDate = new Date(lastViewedTime)

    db.collection('orders').where({
      publisherId: myOpenId,
      status: 'accepted',
      acceptTime: _.gt(lastViewedDate)
    }).count({
      success: function (res) {
        var newCount = res.total || 0
        that.setData({
          newAcceptedCount: newCount,
          mineUnreadCount: 0,
          acceptUnreadCount: 0
        })
        if (that.data.viewType !== 'mine') {
          commonUtil.updateTabBarBadge({ msgCount: newCount })
        } else {
          commonUtil.updateTabBarBadge({ msgCount: 0 })
        }
      },
      fail: function () {
        commonUtil.updateTabBarBadge({ msgCount: 0 })
      }
    })
  },

  /**
   * 批量查询未读消息数
   * @param {Array} ordersList - 订单列表
   */
  loadUnreadCounts: function (ordersList) {
    var that = this
    var myOpenId = wx.getStorageSync('myOpenId') || ''
    if (!myOpenId) {
      var userInfo = app.globalData.userInfo
      myOpenId = userInfo && userInfo._openid ? userInfo._openid : ''
    }
    if (!myOpenId) {
      var cachedUser = wx.getStorageSync('userInfo') || ''
      try { cachedUser = JSON.parse(cachedUser) } catch(e) { cachedUser = {} }
      myOpenId = cachedUser._openid || ''
    }
    if (!myOpenId) return

    var db = wx.cloud.database()
    var _ = db.command

    // 收集需要查询未读的订单ID
    var orderIds = []
    for (var i = 0; i < ordersList.length; i++) {
      var order = ordersList[i]
      if (order.status === 'accepted' || order.status === 'delivered') {
        orderIds.push(order._id)
      }
    }

    if (orderIds.length === 0) return

    // 一次查询所有订单的未读消息，按orderId分组
    db.collection('messages').where({
      orderId: _.in(orderIds),
      senderId: _.neq(myOpenId),
      isRead: _.neq(true)
    }).limit(100).get({
      success: function (res) {
        var list = res.data || []
        // 按订单ID统计未读数量
        var countMap = {}
        for (var j = 0; j < list.length; j++) {
          var oid = list[j].orderId
          countMap[oid] = (countMap[oid] || 0) + 1
        }
        // 更新订单列表
        for (var k = 0; k < ordersList.length; k++) {
          ordersList[k].unreadCount = countMap[ordersList[k]._id] || 0
        }
        that.setData({ orders: ordersList })
        // 更新底部 tabbar 红点
        var totalUnread = 0
        for (var m in countMap) {
          totalUnread += countMap[m]
        }
        commonUtil.updateTabBarBadge({ msgCount: totalUnread })
      },
      fail: function () {}
    })
  },


})


