/**
 * 公共工具函数模块
 * 封装各页面重复使用的工具函数，减少代码冗余
 */

/**
 * 格式化相对时间（如：刚刚、5分钟前、3小时前、2天前）
 * @param {String|Date|Number} date - 日期对象或时间戳
 * @returns {String} 格式化后的相对时间
 */
function formatTime(date) {
  if (!date) return ''
  var d = new Date(date)
  var now = new Date()
  var diff = (now - d) / 1000
  if (diff < 0) return '刚刚'
  if (diff < 60) return '刚刚'
  if (diff < 3600) return Math.floor(diff / 60) + '分钟前'
  if (diff < 86400) return Math.floor(diff / 3600) + '小时前'
  if (diff < 604800) return Math.floor(diff / 86400) + '天前'
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0')
}

/**
 * 格式化完整日期时间（如：2024-01-15 14:30）
 * @param {String|Date|Number} date - 日期对象或时间戳
 * @returns {String} 格式化后的日期时间
 */
function formatDateTime(date) {
  if (!date) return ''
  var d = new Date(date)
  return d.getFullYear() + '-' +
    String(d.getMonth() + 1).padStart(2, '0') + '-' +
    String(d.getDate()).padStart(2, '0') + ' ' +
    String(d.getHours()).padStart(2, '0') + ':' +
    String(d.getMinutes()).padStart(2, '0')
}

/**
 * 获取当前登录用户信息（统一封装缓存读取和解析）
 * @returns {Object} 用户信息对象，包含 phone、nickName、_openid 等
 */
function getUserInfo() {
  var userInfoStr = wx.getStorageSync('userInfo') || ''
  var userInfo = {}
  if (userInfoStr) {
    try { userInfo = JSON.parse(userInfoStr) } catch (e) {}
  }
  // 合并 globalData 中的用户信息
  var app = getApp()
  if (app && app.globalData && app.globalData.userInfo) {
    userInfo = Object.assign({}, app.globalData.userInfo, userInfo)
  }
  return userInfo || {}
}

/**
 * 获取当前用户 openid
 * @returns {String} 用户 openid
 */
function getOpenId() {
  return wx.getStorageSync('myOpenId') || ''
}

/**
 * 节流函数：限制函数在一定时间内只能执行一次
 * @param {Function} fn - 要执行的函数
 * @param {Number} delay - 延迟时间（毫秒）
 * @returns {Function} 节流后的函数
 */
function throttle(fn, delay) {
  var lastTime = 0
  return function() {
    var now = Date.now()
    if (now - lastTime >= delay) {
      lastTime = now
      fn.apply(this, arguments)
    }
  }
}

/**
 * 防抖函数：延迟执行，如果在延迟期间再次调用则重新计时
 * @param {Function} fn - 要执行的函数
 * @param {Number} delay - 延迟时间（毫秒）
 * @returns {Function} 防抖后的函数
 */
function debounce(fn, delay) {
  var timer = null
  return function() {
    var context = this
    var args = arguments
    if (timer) clearTimeout(timer)
    timer = setTimeout(function() {
      fn.apply(context, args)
    }, delay)
  }
}

/**
 * 图片智能压缩：循环压缩直到文件大小 < maxSizeKB
 * @param {String} filePath - 图片本地路径
 * @param {Number} maxSizeKB - 最大文件大小（KB），默认100
 * @returns {Promise<String>} 压缩后的图片路径
 */
function compressImageToSize(filePath, maxSizeKB) {
  maxSizeKB = maxSizeKB || 100
  return new Promise(function(resolve) {
    // 先获取文件信息
    wx.getFileInfo({
      filePath: filePath,
      success: function(fileInfo) {
        var sizeKB = fileInfo.size / 1024
        // 如果已经小于限制，直接返回
        if (sizeKB <= maxSizeKB) {
          resolve(filePath)
          return
        }
        // 根据文件大小计算初始压缩质量
        var quality = Math.max(10, Math.min(80, Math.floor(maxSizeKB / sizeKB * 80)))
        tryCompress(filePath, quality, maxSizeKB, resolve)
      },
      fail: function() {
        // 获取不到文件信息，尝试默认压缩
        tryCompress(filePath, 60, maxSizeKB, resolve)
      }
    })
  })
}

/**
 * 尝试压缩图片（内部递归函数）
 */
function tryCompress(filePath, quality, maxSizeKB, resolve) {
  wx.compressImage({
    src: filePath,
    quality: quality,
    success: function(res) {
      var tempPath = res.tempFilePath || filePath
      // 检查压缩后大小
      wx.getFileInfo({
        filePath: tempPath,
        success: function(info) {
          var sizeKB = info.size / 1024
          if (sizeKB <= maxSizeKB || quality <= 10) {
            resolve(tempPath)
          } else {
            // 仍然太大，继续降低质量压缩
            var newQuality = Math.max(10, quality - 15)
            tryCompress(filePath, newQuality, maxSizeKB, resolve)
          }
        },
        fail: function() {
          resolve(tempPath)
        }
      })
    },
    fail: function() {
      resolve(filePath)
    }
  })
}

/**
 * 压缩视频
 * @param {String} filePath - 视频本地路径
 * @param {Number} maxSizeMB - 最大文件大小（MB），默认10
 * @returns {Promise<String>} 压缩后的视频路径
 */
function compressVideo(filePath, maxSizeMB) {
  maxSizeMB = maxSizeMB || 10
  return new Promise(function(resolve) {
    // 先检查视频大小
    wx.getFileInfo({
      filePath: filePath,
      success: function(fileInfo) {
        var sizeMB = fileInfo.size / 1024 / 1024
        if (sizeMB <= maxSizeMB) {
          resolve(filePath)
          return
        }
        // 需要压缩，计算合适的码率
        var bitrate = Math.max(500, Math.floor(2000 / (sizeMB / maxSizeMB)))
        wx.compressVideo({
          src: filePath,
          bitrate: bitrate,
          fps: 30,
          resolution: 0.5, // 分辨率缩放为原视频的50%
          success: function(res) {
            resolve(res.tempFilePath || filePath)
          },
          fail: function() {
            resolve(filePath)
          }
        })
      },
      fail: function() {
        resolve(filePath)
      }
    })
  })
}

/**
 * 缓存管理：带过期时间的本地存储
 */
var Cache = {
  set: function(key, data, expireMinutes) {
    expireMinutes = expireMinutes || 5
    var item = {
      data: data,
      expire: Date.now() + expireMinutes * 60 * 1000
    }
    wx.setStorageSync('cache_' + key, item)
  },
  get: function(key) {
    var item = wx.getStorageSync('cache_' + key)
    if (!item) return null
    if (Date.now() > item.expire) {
      wx.removeStorageSync('cache_' + key)
      return null
    }
    return item.data
  },
  remove: function(key) {
    wx.removeStorageSync('cache_' + key)
  },
  clear: function() {
    var keys = wx.getStorageInfoSync().keys || []
    for (var i = 0; i < keys.length; i++) {
      if (keys[i].indexOf('cache_') === 0) {
        wx.removeStorageSync(keys[i])
      }
    }
  }
}

/**
 * 图片URL缓存：缓存cloud:// fileID到临时URL的映射，避免重复转换
 */
var ImageUrlCache = {
  _cache: {},
  _expireTime: 30 * 60 * 1000, // 30分钟过期

  set: function(fileID, url) {
    this._cache[fileID] = { url: url, timestamp: Date.now() }
  },

  get: function(fileID) {
    var item = this._cache[fileID]
    if (!item) return null
    if (Date.now() - item.timestamp > this._expireTime) {
      delete this._cache[fileID]
      return null
    }
    return item.url
  },

  getMany: function(fileIDs) {
    var result = {}
    var needConvert = []
    for (var i = 0; i < fileIDs.length; i++) {
      var id = fileIDs[i]
      var url = this.get(id)
      if (url) {
        result[id] = url
      } else {
        needConvert.push(id)
      }
    }
    return { cached: result, needConvert: needConvert }
  }
}

/**
 * 批量转换 fileID 为临时 URL（带缓存）
 * @param {Array} fileIDs - cloud:// 格式的文件ID数组
 * @returns {Promise<Object>} 映射对象 { fileID: url }
 */
function batchConvertFileIDs(fileIDs) {
  return new Promise(function(resolve) {
    if (!fileIDs || fileIDs.length === 0) {
      resolve({})
      return
    }

    var cacheResult = ImageUrlCache.getMany(fileIDs)
    if (cacheResult.needConvert.length === 0) {
      resolve(cacheResult.cached)
      return
    }

    wx.cloud.getTempFileURL({
      fileList: cacheResult.needConvert,
      success: function(res) {
        if (!res || !res.fileList) {
          resolve(cacheResult.cached)
          return
        }
        var urlMap = {}
        for (var i = 0; i < res.fileList.length; i++) {
          var item = res.fileList[i]
          if (item.tempFileURL) {
            urlMap[item.fileID] = item.tempFileURL
            ImageUrlCache.set(item.fileID, item.tempFileURL)
          }
        }
        resolve(Object.assign({}, cacheResult.cached, urlMap))
      },
      fail: function() {
        resolve(cacheResult.cached)
      }
    })
  })
}

/**
 * 转换订单中的图片 fileID 为临时 URL
 * @param {Array} orders - 订单数组
 * @returns {Promise}
 */
function convertOrderImages(orders) {
  return new Promise(function(resolve) {
    if (!orders || orders.length === 0) {
      resolve()
      return
    }

    var fileIDs = []
    var mappings = []

    for (var i = 0; i < orders.length; i++) {
      var order = orders[i]
      if (order.productImages && Array.isArray(order.productImages)) {
        for (var j = 0; j < order.productImages.length; j++) {
          if (typeof order.productImages[j] === 'string' && order.productImages[j].indexOf('cloud://') === 0) {
            fileIDs.push(order.productImages[j])
            mappings.push({ orderIndex: i, field: 'productImages', index: j })
          }
        }
      }
      if (order.otherImages && Array.isArray(order.otherImages)) {
        for (var k = 0; k < order.otherImages.length; k++) {
          if (typeof order.otherImages[k] === 'string' && order.otherImages[k].indexOf('cloud://') === 0) {
            fileIDs.push(order.otherImages[k])
            mappings.push({ orderIndex: i, field: 'otherImages', index: k })
          }
        }
      }
      if (order.deliveryPhoto && typeof order.deliveryPhoto === 'string' && order.deliveryPhoto.indexOf('cloud://') === 0) {
        fileIDs.push(order.deliveryPhoto)
        mappings.push({ orderIndex: i, field: 'deliveryPhoto', index: -1 })
      }
    }

    if (fileIDs.length === 0) {
      resolve()
      return
    }

    batchConvertFileIDs(fileIDs).then(function(urlMap) {
      for (var m = 0; m < mappings.length; m++) {
        var map = mappings[m]
        var order = orders[map.orderIndex]
        if (map.index >= 0) {
          var originalID = order[map.field][map.index]
          if (urlMap[originalID]) {
            order[map.field][map.index] = urlMap[originalID]
          }
        } else {
          var originalID = order[map.field]
          if (urlMap[originalID]) {
            order[map.field] = urlMap[originalID]
          }
        }
      }
      resolve()
    }).catch(function() {
      resolve()
    })
  })
}

/**
 * 转换聊天消息中的图片 fileID 为临时 URL
 * @param {Array} messages - 消息数组
 * @returns {Promise}
 */
function convertChatImages(messages) {
  return new Promise(function(resolve) {
    if (!messages || messages.length === 0) {
      resolve()
      return
    }

    var fileIDs = []
    var indexes = []

    for (var i = 0; i < messages.length; i++) {
      var msg = messages[i]
      if (msg.imageUrl && typeof msg.imageUrl === 'string' && msg.imageUrl.indexOf('cloud://') === 0) {
        fileIDs.push(msg.imageUrl)
        indexes.push(i)
      }
    }

    if (fileIDs.length === 0) {
      resolve()
      return
    }

    batchConvertFileIDs(fileIDs).then(function(urlMap) {
      for (var j = 0; j < indexes.length; j++) {
        var idx = indexes[j]
        var originalID = messages[idx].imageUrl
        if (urlMap[originalID]) {
          messages[idx].imageUrl = urlMap[originalID]
        }
      }
      resolve()
    }).catch(function() {
      resolve()
    })
  })
}

/**
 * 更新底部 tabbar 未读红点
 * @param {Object} options - { msgCount: 消息未读数, notifyCount: 通知未读数 }
 */
function updateTabBarBadge(options) {
  options = options || {}
  try {
    var pages = getCurrentPages()
    var currentPage = pages[pages.length - 1]
    if (currentPage && currentPage.getTabBar) {
      var tabBar = currentPage.getTabBar()
      if (tabBar) {
        var data = {}
        if (options.msgCount !== undefined) {
          data.unreadMsgCount = options.msgCount
        }
        if (options.notifyCount !== undefined) {
          data.unreadNotifyCount = options.notifyCount
        }
        if (Object.keys(data).length > 0) {
          tabBar.setData(data)
        }
      }
    }
  } catch (e) {}
}

/**
 * 加载全局未读消息数并更新 tabbar
 * 统计所有未读消息，自动更新 tabbar 红点
 * @returns {Promise<Number>} 总未读数
 */
function loadGlobalUnreadMsg() {
  return new Promise(function(resolve) {
    var myOpenId = getOpenId()
    if (!myOpenId) {
      resolve(0)
      return
    }

    try {
      var db = wx.cloud.database()
      var _ = db.command
      var lastViewedTime = wx.getStorageSync('lastViewedOrdersTime') || 0
      var lastViewedDate = new Date(lastViewedTime)

      db.collection('orders').where({
        publisherId: myOpenId,
        status: 'accepted',
        acceptTime: _.gt(lastViewedDate)
      }).count({
        success: function (res) {
          var total = res.total || 0
          updateTabBarBadge({ msgCount: total })
          resolve(total)
        },
        fail: function () {
          resolve(0)
        }
      })
    } catch (e) {
      resolve(0)
    }
  })
}

module.exports = {
  formatTime: formatTime,
  formatDateTime: formatDateTime,
  getUserInfo: getUserInfo,
  getOpenId: getOpenId,
  throttle: throttle,
  debounce: debounce,
  compressImageToSize: compressImageToSize,
  compressVideo: compressVideo,
  Cache: Cache,
  batchConvertFileIDs: batchConvertFileIDs,
  convertOrderImages: convertOrderImages,
  convertChatImages: convertChatImages,
  updateTabBarBadge: updateTabBarBadge,
  loadGlobalUnreadMsg: loadGlobalUnreadMsg
}