// 云函数：发布搬水订单
// 改造：如果用户不存在则自动创建，手机号从表单传入
const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command

exports.main = async function(event, context) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID

  try {
    // ===== 参数校验 =====

    // 手机号格式校验
    const phone = (event.phone || '').trim()
    const phoneReg = /^1[2-9]\d{9}$/
    if (!phoneReg.test(phone)) {
      return { code: -1, msg: '请输入正确的11位手机号' }
    }

    // 分类参数（提前获取，后续校验需要判断分类）
    const category = event.category || 'water'

    // 宿舍信息校验（仅搬水、跑腿需要）
    var building = ''
    var floorNum = 0
    var room = ''
    if (category === 'water' || category === 'errand') {
      building = (event.building || '').trim()
      if (!building) {
        return { code: -1, msg: '请输入宿舍楼栋' }
      }
      floorNum = parseInt(event.floor)
      if (isNaN(floorNum) || floorNum < 1 || floorNum > 9) {
        return { code: -1, msg: '楼层必须在1-9之间' }
      }
      room = (event.room || '').trim()
      if (!room) {
        return { code: -1, msg: '请输入房间号' }
      }
    }

    // 水桶数量校验（仅搬水分类）
    var count = parseInt(event.count) || 1
    if (category === 'water' && (count < 1 || count > 5)) {
      return { code: -1, msg: '水桶数量必须在1-5之间' }
    }

    // 金额校验
    var price = parseFloat(event.price)
    if (isNaN(price)) price = 0
    if (category === 'water' || category === 'errand' || category === 'substitute') {
      if (price < 1 || price > 20) {
        return { code: -1, msg: '报酬金额需在1-20元之间' }
      }
    } else if (category === 'secondhand') {
      if (price < 0 || price > 1000) {
        return { code: -1, msg: '价格需在0-1000元之间' }
      }
    }

    // 期望送达时间校验（仅搬水、跑腿需要）
    const deliveryTime = (event.deliveryTime || '').trim()
    if ((category === 'water' || category === 'errand') && !deliveryTime) {
      return { code: -1, msg: '请选择期望送达时间' }
    }

    // 备注长度限制
    const remark = (event.remark || '').trim()
    if (remark.length > 200) {
      return { code: -1, msg: '备注不能超过200字' }
    }
    // 商品图片（二手分类）
    const productImages = event.productImages || []
    // 代课专属字段
    const classDate = event.classDate || ''
    const classSection = event.classSection || ''
    const className = event.className || ''
    const classLocation = event.classLocation || ''

    // ===== 防刷：同一用户1分钟内不能重复发布 =====
    const oneMinAgo = new Date(Date.now() - 60000)
    const recentOrders = await db.collection('orders').where({
      publisherId: openid,
      createTime: _.gte(oneMinAgo)
    }).count()
    if (recentOrders.total > 0) {
      return { code: -1, msg: '发布太频繁，请稍后再试' }
    }

    // 检查信用分
    const creditUserResult = await db.collection('users').where({ _openid: openid }).get()
    if (creditUserResult.data.length > 0) {
      const creditUser = creditUserResult.data[0]
      if (creditUser.creditScore < 40) {
        return { code: -1, msg: '信用分过低（低于40分），暂时无法发布需求' }
      }
    }

    // 获取或自动创建发布者信息（复用信用分检查的查询结果，仅当新用户时创建）
    let userInfo
    if (creditUserResult.data.length === 0) {
      // 新用户，自动创建记录
      var lastFour = phone.substring(7)
      var nickName = '用户' + lastFour
      const newUser = {
        _openid: openid,
        nickName: nickName,
        avatarUrl: '',
        phone: phone,
        building: building,
        floor: floorNum,
        room: room,
        school: event.school || '广东江门中医药职业学院',
        creditScore: 100,
        orderCount: 0,
        helpCount: 0,
        rating: 0,
        ratingCount: 0,
        createTime: db.serverDate()
      }
      const addResult = await db.collection('users').add({ data: newUser })
      userInfo = { ...newUser, _id: addResult._id }
    } else {
      userInfo = creditUserResult.data[0]
      // 同步更新用户的手机号和宿舍信息
      var updateFields = { phone: phone }
      if (category === 'water' || category === 'errand') {
        if (building) updateFields.building = building
        if (floorNum) updateFields.floor = floorNum
        if (room) updateFields.room = room
      }
      if (!userInfo._openid) {
        updateFields._openid = openid
      }
      await db.collection('users').doc(userInfo._id).update({
        data: updateFields
      })
    }

    // 生成订单编号：WP + 年月日 + 6位随机数
    const now = new Date()
    const dateStr = now.getFullYear().toString() +
      String(now.getMonth() + 1).padStart(2, '0') +
      String(now.getDate()).padStart(2, '0')
    const randomStr = String(Math.floor(Math.random() * 1000000)).padStart(6, '0')
    const orderNo = 'WP' + dateStr + randomStr

    // 创建订单
    const order = {
      orderNo: orderNo,
      status: 'pending',
      category: category,
      school: event.school || '广东江门中医药职业学院',
      publisherId: openid,
      publisherName: userInfo.nickName || '用户',
      publisherPhone: phone,
      acceptorId: '',
      acceptorName: '',
      building: building,
      floor: floorNum,
      room: room,
      count: count,
      price: price,
      remark: remark,
      deliveryTime: deliveryTime,
      productImages: productImages,
      classDate: classDate,
      classSection: classSection,
      className: className,
      classLocation: classLocation,
      rating: 0,
      reviewContent: '',
      createTime: db.serverDate()
    }

    const addResult = await db.collection('orders').add({ data: order })

    // 更新用户发布订单数
    await db.collection('users').where({ _openid: openid }).update({
      data: { orderCount: _.inc(1) }
    })

    return {
      code: 0,
      msg: '发布成功',
      data: { ...order, _id: addResult._id }
    }
  } catch (err) {
    return { code: -1, msg: '发布失败', err: err.message }
  }
}
