// 云函数：编辑订单（更新 pending 状态的订单信息）
// 只有发布者可以编辑，且只能编辑 pending 状态的订单
const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()

exports.main = async function(event, context) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID
  const orderId = event.orderId

  if (!orderId) {
    return { code: -1, msg: '缺少订单ID' }
  }

  try {
    // 获取订单
    const orderResult = await db.collection('orders').doc(orderId).get()
    if (!orderResult.data) {
      return { code: -1, msg: '订单不存在' }
    }
    const order = orderResult.data

    // 只有发布者可以编辑
    if (order.publisherId !== openid) {
      return { code: -1, msg: '只有发布者可以修改订单' }
    }

    // 只能编辑 pending 状态的订单
    if (order.status !== 'pending') {
      return { code: -1, msg: '订单已被接单，无法修改' }
    }

    const category = order.category || 'water'
    const updateData = {}

    // 手机号校验（所有分类都需要）
    const phone = (event.phone || '').trim()
    const phoneReg = /^1[2-9]\d{9}$/
    if (!phoneReg.test(phone)) {
      return { code: -1, msg: '请输入正确的11位手机号' }
    }
    updateData.publisherPhone = phone

    // 搬水、跑腿分类：楼栋、楼层、房间、数量、价格、送达时间
    if (category === 'water' || category === 'errand') {
      const building = (event.building || '').trim()
      if (!building) {
        return { code: -1, msg: '请输入宿舍楼栋' }
      }

      const floorNum = parseInt(event.floor)
      if (isNaN(floorNum) || floorNum < 1 || floorNum > 9) {
        return { code: -1, msg: '楼层必须在1-9之间' }
      }

      const room = (event.room || '').trim()
      if (!room) {
        return { code: -1, msg: '请输入房间号' }
      }

      const price = parseFloat(event.price)
      if (isNaN(price) || price < 1 || price > 20) {
        return { code: -1, msg: '报酬金额需在1-20元之间' }
      }

      const deliveryTime = (event.deliveryTime || '').trim()
      if (!deliveryTime) {
        return { code: -1, msg: '请选择期望送达时间' }
      }

      updateData.building = building
      updateData.floor = floorNum
      updateData.room = room
      updateData.price = price
      updateData.deliveryTime = deliveryTime

      // 搬水分类：水桶数量
      if (category === 'water') {
        const count = parseInt(event.count) || 1
        if (count < 1 || count > 5) {
          return { code: -1, msg: '水桶数量必须在1-5之间' }
        }
        updateData.count = count
      }
    }

    // 代课分类：价格、课程信息
    if (category === 'substitute') {
      const price = parseFloat(event.price)
      if (isNaN(price) || price < 1 || price > 20) {
        return { code: -1, msg: '报酬金额需在1-20元之间' }
      }
      updateData.price = price

      if (event.classDate !== undefined) updateData.classDate = event.classDate
      if (event.classSection !== undefined) updateData.classSection = event.classSection
      if (event.className !== undefined) updateData.className = event.className
      if (event.classLocation !== undefined) updateData.classLocation = event.classLocation
    }

    // 二手分类：价格、描述
    if (category === 'secondhand') {
      const price = parseFloat(event.price)
      if (isNaN(price) || price < 0 || price > 1000) {
        return { code: -1, msg: '价格需在0-1000元之间' }
      }
      updateData.price = price
    }

    // 备注（所有分类都可修改）
    if (event.remark !== undefined) {
      const remark = (event.remark || '').trim()
      if (remark.length > 200) {
        return { code: -1, msg: '备注不能超过200字' }
      }
      updateData.remark = remark
    }

    // 更新订单
    await db.collection('orders').doc(orderId).update({
      data: updateData
    })

    return { code: 0, msg: '修改成功' }
  } catch (err) {
    return { code: -1, msg: '修改失败', err: err.message }
  }
}
