/**
 * 帮到位小程序 - 入口文件（云开发版）
 * 启动时自动用微信openid静默登录
 */

App({
  onLaunch: function() {
    if (!wx.cloud) {
      console.error('[帮到位] 请使用 2.2.3 或以上的基础库以使用云能力')
      return
    }
    wx.cloud.init({
      env: 'cloud1-d0g3183gq3008eb9d',
      traceUser: true
    })
    this.autoLogin()
  },

  /**
   * 自动登录：静默创建/获取用户记录（带随机昵称）
   * 不拦截，失败不影响使用
   */
  autoLogin: function() {
    var that = this
    // 先从缓存读取
    var cachedId = ''
    try {
      var cached = wx.getStorageSync('userInfo')
      if (cached) {
        var userInfo = JSON.parse(cached)
        if (userInfo && (userInfo._openid || userInfo._id)) {
          that.globalData.userInfo = userInfo
          that.globalData.isLoggedIn = true
          that.globalData.isNewUser = false
          that.globalData.isProfileCompleted = !!(userInfo.phone && userInfo.nickName)
          if (userInfo._openid) {
            wx.setStorageSync('myOpenId', userInfo._openid)
          }
          cachedId = userInfo._id || ''
          return
        }
      }
    } catch (e) {}

    // 调用云函数自动创建/获取用户
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'autoCreate', _id: cachedId },
      success: function (res) {
        if (res.result && res.result.code === 0) {
          var userInfo = res.result.data || {}
          wx.setStorageSync('userInfo', JSON.stringify(userInfo))
          that.globalData.userInfo = userInfo
          that.globalData.isLoggedIn = true
          that.globalData.isNewUser = userInfo.isNew ? true : false
          that.globalData.isProfileCompleted = !!(userInfo.phone && userInfo.nickName)
          if (userInfo._openid) {
            wx.setStorageSync('myOpenId', userInfo._openid)
          }
          // 检查连续登录恢复信誉分
          that.checkConsecutiveLogin()
        }
      },
      fail: function () {
        // 静默登录失败不影响使用
      }
    })
  },

  /**
   * 检查连续登录天数，每3天恢复5分信誉分（最高100分）
   */
  checkConsecutiveLogin: function () {
    var that = this
    var today = new Date().toDateString()
    var lastLogin = wx.getStorageSync('lastLoginDate') || ''
    var consecutiveDays = wx.getStorageSync('consecutiveDays') || 0

    if (lastLogin === today) {
      return
    }

    var yesterday = new Date(Date.now() - 86400000).toDateString()
    if (lastLogin === yesterday) {
      consecutiveDays = parseInt(consecutiveDays) + 1
    } else if (lastLogin !== today) {
      consecutiveDays = 1
    }

    wx.setStorageSync('lastLoginDate', today)
    wx.setStorageSync('consecutiveDays', consecutiveDays)

    if (consecutiveDays > 0 && consecutiveDays % 3 === 0) {
      wx.cloud.callFunction({
        name: 'login',
        data: { action: 'restoreCredit', _id: (that.globalData.userInfo && that.globalData.userInfo._id) || '' },
        success: function (res) {
          if (res.result && res.result.code === 0) {
            wx.setStorageSync('userInfo', JSON.stringify(res.result.data))
            that.globalData.userInfo = res.result.data
            wx.showToast({ title: '信誉分+5', icon: 'none' })
          }
        }
      })
    }
  },

  /**
   * 检查登录状态，返回是否已登录
   */
  checkLoginAndProfile: function () {
    var that = this
    if (!that.globalData.userInfo || !that.globalData.userInfo._openid) {
      that.autoLogin()
      return false
    }
    return true
  },

  globalData: {
    userInfo: null,
    isLoggedIn: false,
    isNewUser: true,
    isProfileCompleted: false,
    ordersViewType: '',
    cloudEnvId: 'cloud1-d0g3183gq3008eb9d',
    hasPhone: function () {
      return !!(this.userInfo && this.userInfo.phone)
    },
    hasNickName: function () {
      return !!(this.userInfo && this.userInfo.nickName)
    }
  }
})
