// acceptOrder/index.js
// 云函数：接单
const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command

function formatDate(date) {
  var y = date.getFullYear()
  var m = ('0' + (date.getMonth() + 1)).slice(-2)
  var d = ('0' + date.getDate()).slice(-2)
  var h = ('0' + date.getHours()).slice(-2)
  var min = ('0' + date.getMinutes()).slice(-2)
  var s = ('0' + date.getSeconds()).slice(-2)
  return y + '-' + m + '-' + d + ' ' + h + ':' + min + ':' + s
}

exports.main = async function(event, context) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID
  const orderId = event.orderId

  if (!orderId) {
    return { code: -1, msg: '缺少订单ID' }
  }

  try {
    // ===== 防刷：同一用户5秒内不能重复接单 =====
    const fiveSecAgo = new Date(Date.now() - 5000)
    const recentAccept = await db.collection('orders').where({
      acceptorId: openid,
      acceptTime: _.gte(fiveSecAgo)
    }).count()
    if (recentAccept.total > 0) {
      return { code: -1, msg: '操作太频繁，请稍后再试' }
    }

    // 获取接单者信息，如果没有则自动创建
    let userResult = await db.collection('users').where({ _openid: openid }).get()
    let userInfo

    if (userResult.data.length === 0) {
      var randomNum = String(Math.floor(Math.random() * 10000)).padStart(4, '0')
      const newUser = {
        _openid: openid,
        nickName: '用户' + randomNum,
        avatarUrl: '',
        phone: '',
        building: '',
        floor: '',
        room: '',
        creditScore: 100,
        orderCount: 0,
        helpCount: 0,
        rating: 0,
        ratingCount: 0,
        createTime: db.serverDate()
      }
      const addResult = await db.collection('users').add({ data: newUser })
      userInfo = { ...newUser, _id: addResult._id }
    } else {
      userInfo = userResult.data[0]
    }

    // 信用分低于60禁止接单
    if ((userInfo.creditScore || 100) < 60) {
      return { code: -1, msg: '你的信用分不足60分，无法接单' }
    }

    // 检查订单是否存在且状态为 pending
    const orderResult = await db.collection('orders').doc(orderId).get()
    if (!orderResult.data) {
      return { code: -1, msg: '订单不存在' }
    }
    if (orderResult.data.status !== 'pending') {
      return { code: -1, msg: '该订单已被接单' }
    }
    if (orderResult.data.publisherId === openid) {
      return { code: -1, msg: '不能接自己的订单' }
    }

    // ===== 防重复接单：使用条件更新，确保原子性 =====
    // 只有 status 仍然为 pending 时才更新，防止并发接单
    const updateResult = await db.collection('orders').where({
      _id: orderId,
      status: 'pending'
    }).update({
      data: {
        status: 'accepted',
        acceptorId: openid,
        acceptorName: userInfo.nickName || '匿名用户',
        acceptorPhone: userInfo.phone || '',
        acceptTime: db.serverDate()
      }
    })

    // 检查是否真的更新成功（可能已被其他人抢先接单）
    if (!updateResult.stats || updateResult.stats.updated === 0) {
      return { code: -1, msg: '该订单已被其他人接单' }
    }

    // 更新用户帮助次数
    await db.collection('users').where({ _openid: openid }).update({
      data: { helpCount: _.inc(1) }
    })

    // 发送订阅消息通知发布者（有人接单了）
    try {
      var order = orderResult.data
      var acceptorName = userInfo.nickName || '同学'
      await cloud.callFunction({
        name: 'sendNotification',
        data: {
          touser: order.publisherId,
          templateId: 'NN3zfnGZHRpc8S9UPGYG1nop3OSBwmQ5LCuSYlbxRfw',
          page: 'pages/order-detail/order-detail?id=' + orderId,
          data: {
            phrase15: { value: (order.categoryText || order.category || '搬水') + '服务' },
            thing17: { value: acceptorName },
            time16: { value: formatDate(new Date()) },
            thing28: { value: order.price ? order.price + '元' : '面议' },
            name1: { value: order.publisherName || '同学' }
          }
        }
      })
    } catch (notifyErr) {
      console.log('通知发送失败:', notifyErr)
    }

    return { code: 0, msg: '接单成功' }
  } catch (err) {
    return { code: -1, msg: '接单失败', err: err.message }
  }
}
