const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command

const MAX_LIMIT = 100

exports.main = async function(event, context) {
  try {
    const now = new Date()
    let expiredCount = 0

    // 分批处理有时间限制的订单（搬水、跑腿、代课）
    let hasMore = true
    while (hasMore) {
      const batch = await db.collection('orders').where({
        status: 'pending',
        category: _.in(['water', 'errand', 'substitute']),
        deliveryTime: _.neq('')
      }).limit(MAX_LIMIT).get()

      for (let order of batch.data) {
        if (!order.deliveryTime) continue
        const deliveryDate = new Date(order.deliveryTime)
        if (deliveryDate.getTime() < now.getTime()) {
          await db.collection('orders').doc(order._id).update({
            data: {
              status: 'expired',
              expireTime: now,
              updateTime: db.serverDate()
            }
          })
          expiredCount++
        }
      }

      hasMore = batch.data.length === MAX_LIMIT
    }

    // 二手分类：30天有效期，同样分批处理
    const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000)
    hasMore = true
    while (hasMore) {
      const batch = await db.collection('orders').where({
        status: 'pending',
        category: 'secondhand'
      }).limit(MAX_LIMIT).get()

      for (let order of batch.data) {
        if (!order.createTime) continue
        const createDate = new Date(order.createTime)
        if (createDate.getTime() < thirtyDaysAgo.getTime()) {
          await db.collection('orders').doc(order._id).update({
            data: {
              status: 'expired',
              expireTime: now,
              updateTime: db.serverDate()
            }
          })
          expiredCount++
        }
      }

      hasMore = batch.data.length === MAX_LIMIT
    }

    return {
      code: 0,
      msg: '过期订单处理完成',
      data: {
        expiredCount: expiredCount
      }
    }
  } catch (err) {
    console.error('[帮到位] expireOrders云函数失败', err)
    return {
      code: -1,
      msg: '处理失败',
      err: err.message
    }
  }
}
