// 意见反馈页面

Page({

  /**
   * 页面的初始数据
   */
  data: {
    // 当前选中的反馈类型索引
    typeIndex: 0,
    // 反馈类型选项列表
    types: ['功能建议', 'Bug反馈', '体验问题', '其他'],
    // 反馈内容
    content: '',
    // 联系方式
    contact: '',
    // 是否正在提交
    submitting: false
  },

  /**
   * 页面加载时自动填充注册手机号
   */
  onLoad: function () {
    var userInfoStr = wx.getStorageSync('userInfo') || ''
    var userInfo = {}
    if (userInfoStr) {
      try { userInfo = JSON.parse(userInfoStr) } catch (e) {}
    }
    if (userInfo.phone) {
      this.setData({ contact: userInfo.phone })
    }
  },

  /**
   * 反馈类型选择变更
   */
  bindTypeChange: function (e) {
    this.setData({
      typeIndex: e.detail.value
    });
  },

  /**
   * 反馈内容输入
   */
  bindContentInput: function (e) {
    this.setData({
      content: e.detail.value
    });
  },

  /**
   * 联系方式输入
   */
  bindContactInput: function (e) {
    this.setData({
      contact: e.detail.value
    });
  },

  /**
   * 提交反馈
   */
  onSubmit: function () {
    var that = this;

    // 防止重复提交
    if (that.data.submitting) {
      return;
    }

    // 验证反馈内容是否为空
    if (!that.data.content || that.data.content.trim() === '') {
      wx.showToast({
        title: '请输入反馈内容',
        icon: 'none',
        duration: 2000
      });
      return;
    }

    // 设置提交中状态
    that.setData({
      submitting: true
    });

    var submitData = {
      type: that.data.types[that.data.typeIndex],
      content: that.data.content.trim(),
      contact: that.data.contact.trim()
    };

    wx.cloud.callFunction({
      name: 'login',
      data: {
        action: 'submitFeedback',
        type: submitData.type,
        content: submitData.content,
        contact: submitData.contact
      },
      success: function(res) {
        if (res.result && res.result.code === 0) {
          wx.showToast({ title: '提交成功，感谢反馈', icon: 'success', duration: 2000 })
          that.setData({ submitting: false })
          setTimeout(function() { wx.navigateBack() }, 1500)
        } else {
          wx.showToast({ title: (res.result && res.result.msg) || '提交失败', icon: 'none' })
          that.setData({ submitting: false })
        }
      },
      fail: function() {
        wx.showToast({ title: '网络错误', icon: 'none' })
        that.setData({ submitting: false })
      }
    })
  }
});
