var app = getApp()

Page({
  data: {
    nickName: '',
    phone: '',
    userId: ''
  },

  onLoad: function () {
    var userInfo = app.globalData.userInfo || {}
    try {
      var cached = wx.getStorageSync('userInfo')
      if (cached) userInfo = JSON.parse(cached)
    } catch (e) {}
    this.setData({
      nickName: userInfo.nickName || '',
      phone: userInfo.phone || '',
      userId: userInfo._id || ''
    })
  },

  bindNickNameInput: function (e) {
    this.setData({ nickName: e.detail.value })
  },

  bindPhoneInput: function (e) {
    this.setData({ phone: e.detail.value })
  },

  onSave: function () {
    var that = this
    var nickName = (that.data.nickName || '').trim()
    // 昵称改为选填，不填则保持原来的

    var phone = (that.data.phone || '').trim()
    if (!phone) {
      wx.showToast({ title: '手机号不能为空', icon: 'none' })
      return
    }
    if (phone.length !== 11 || !/^\d{11}$/.test(phone)) {
      wx.showToast({ title: '请输入正确的11位手机号', icon: 'none' })
      return
    }

    wx.showLoading({ title: '保存中' })
    wx.cloud.callFunction({
      name: 'login',
      data: {
        action: 'updateProfile',
        _id: that.data.userId,
        nickName: nickName || undefined,
        phone: phone
      },
      success: function (res) {
        wx.hideLoading()
        if (res.result && res.result.code === 0) {
          var userInfo = res.result.data || {}
          wx.setStorageSync('userInfo', JSON.stringify(userInfo))
          app.globalData.userInfo = userInfo
          app.globalData.isProfileCompleted = !!(userInfo.phone && userInfo.nickName)
          wx.showToast({ title: '保存成功', icon: 'success' })
          setTimeout(function () { wx.navigateBack() }, 1500)
        } else {
          wx.showToast({ title: (res.result && res.result.msg) || '保存失败', icon: 'none' })
        }
      },
      fail: function () {
        wx.hideLoading()
        wx.showToast({ title: '网络错误，请重试', icon: 'none' })
      }
    })
  }
})
