const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()
const _ = db.command

function formatDate(date) {
  var y = date.getFullYear()
  var m = ('0' + (date.getMonth() + 1)).slice(-2)
  var d = ('0' + date.getDate()).slice(-2)
  var h = ('0' + date.getHours()).slice(-2)
  var min = ('0' + date.getMinutes()).slice(-2)
  return y + '-' + m + '-' + d + ' ' + h + ':' + min
}

exports.main = async function(event, context) {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID
  const orderId = event.orderId
  const reason = event.reason || ''

  if (!orderId) {
    return { code: -1, msg: '缺少订单ID' }
  }

  try {
    const orderResult = await db.collection('orders').doc(orderId).get()
    if (!orderResult.data) {
      return { code: -1, msg: '订单不存在' }
    }
    const order = orderResult.data

    if (order.publisherId !== openid) {
      const userResult = await db.collection('users').where({ _openid: openid }).get()
      const user = userResult.data.length > 0 ? userResult.data[0] : {}
      var tIsAdmin = user.isAdmin || user['isAdmin ']
      var tIsManager = user.isManager || user['isManager ']
      if (!tIsAdmin && !tIsManager) {
        return { code: -1, msg: '只有发布者或管理员可以取消订单' }
      }
      if ((tIsAdmin || tIsManager) && !event.fromAdmin) {
        return { code: -1, msg: '管理员请通过管理后台取消订单' }
      }
    }

    if (order.status === 'paid') {
      return { code: -1, msg: '订单已完成，无法取消' }
    }
    if (order.status === 'cancelled') {
      return { code: -1, msg: '订单已取消' }
    }
    if (order.status === 'delivered') {
      return { code: -1, msg: '订单已送达，无法取消，请确认付款' }
    }

    var acceptorId = order.acceptorId || ''
    var hadAcceptor = !!(acceptorId && acceptorId !== '' && order.status !== 'pending')

    const updateData = {
      status: 'cancelled',
      cancelTime: db.serverDate(),
      cancelReason: reason ? reason.trim() : '发布者主动取消'
    }

    if (hadAcceptor) {
      updateData.cancelReason = (reason ? reason.trim() : '发布者主动取消') + '（已接单后取消）'
    }

    await db.collection('orders').doc(orderId).update({ data: updateData })

    // orderCount 递减时加下界保护，防止变为负数
    // 扣发布者的订单数，不是当前操作者的
    var publisherId = order.publisherId
    await db.collection('users').where({
      _openid: publisherId,
      orderCount: _.gt(0)
    }).update({
      data: { orderCount: _.inc(-1) }
    })

    if (hadAcceptor) {
      // helpCount 递减时加下界保护
      await db.collection('users').where({
        _openid: acceptorId,
        helpCount: _.gt(0)
      }).update({
        data: { helpCount: _.inc(-1) }
      })

      try {
        await db.collection('messages').where({
          orderId: orderId,
          isRead: false
        }).update({
          data: { isRead: true }
        })
      } catch (msgErr) {
        console.log('取消订单时消息清理失败（不影响主流程）', msgErr.message)
      }

      try {
        await cloud.callFunction({
          name: 'sendNotification',
          data: {
            touser: acceptorId,
            templateId: 'NN3zfnGZHRpc8S9UPGYG1nop3OSBwmQ5LCuSYlbxRfw',
            page: 'pages/order-detail/order-detail?id=' + orderId,
            data: {
              phrase15: { value: '订单被取消' },
              thing17: { value: order.publisherName || '发布者' },
              time16: { value: formatDate(new Date()) },
              thing28: { value: order.price ? order.price + '元' : '面议' },
              name1: { value: order.acceptorName || '同学' }
            }
          }
        })
      } catch (notifyErr) {
        console.log('取消订单通知发送失败（不影响主流程）', notifyErr.message)
      }
    }

    return { code: 0, msg: '已取消订单' }
  } catch (err) {
    return { code: -1, msg: '操作失败', err: err.message }
  }
}
