const app = getApp()
var commonUtil = require('../../utils/common-util.js')

var EMOJI_DATA = {
  smile: ['😀', '😂', '🤣', '😊', '😍', '🥰', '😘', '😜', '🤔', '😎', '🥺', '😭', '😤', '😡', '🤗', '😴', '🤤', '😇', '😏', '🙄', '😬', '🤐', '🤫', '🤭'],
  hand: ['👍', '👎', '👏', '🙌', '🤝', '✌️', '🤞', '👌', '💪', '👋'],
  heart: ['❤️', '💔', '💕', '💞', '💓', '💗', '💖', '💘', '💯', '✨']
}
var EMOJI_TABS = [
  { name: 'smile', icon: '😊' },
  { name: 'hand', icon: '👍' },
  { name: 'heart', icon: '❤️' }
]

Page({
  data: {
    post: null,
    replies: [],
    replyContent: '',
    submitting: false,
    fromAdmin: false,
    replyMode: '',      // '' | 'quote' | 'reply'
    quoteReply: null,   // 引用的回复内容
    quoteFloor: 0,      // 引用的楼层号
    postExpanded: false,
    expandedReplies: {},
    showEmoji: false,
    emojiList: [],
    emojiTabs: [],
    replyImages: []
  },

  onLoad: function(options) {
    if (options.from === 'admin') {
      this.setData({ fromAdmin: true })
    }
    if (options.id) {
      this.setData({ postId: options.id })
      this.loadPost(options.id)
    }
    this.initEmoji()
  },

  loadPost: function(id) {
    var that = this
    wx.showLoading({ title: '加载中' })
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'getPostDetail', _id: id, myOpenId: (app.globalData.userInfo && app.globalData.userInfo._openid) || '' },
      success: function(res) {
        wx.hideLoading()
        if (res.result && res.result.code === 0) {
          var post = res.result.data
          post.createTimeText = commonUtil.formatTime(post.createTime)
          post.rankBadge = that.getRankBadge(post)
          post.isMe = !!post.isMine
          var replies = post.replies || []
          var myOpenId = (app.globalData.userInfo && app.globalData.userInfo._openid) || ''
          replies = replies.map(function(r) {
            r.createTimeText = commonUtil.formatTime(r.createTime)
            r.rankBadge = that.getRankBadge(r)
            r.isMe = !!r.isMine
            r.likeCount = r.likeCount || 0
            var likers = r.likers || []
            r.isLiked = !!(myOpenId && likers.indexOf(myOpenId) > -1)
            return r
          })
          that.setData({ post: post, replies: replies })
          // 记录浏览（每人只记一次）
          wx.cloud.callFunction({
            name: 'login',
            data: { action: 'viewPost', _id: id },
            fail: function() {} // 静默失败
          })
        } else {
          wx.showToast({ title: '帖子不存在', icon: 'none' })
        }
      },
      fail: function() { wx.hideLoading(); wx.showToast({ title: '加载失败', icon: 'none' }) }
    })
  },

  getRankBadge: function(item) {
    if (!item) return ''
    if (item.isAdmin) return '👑 创始人'
    if (item.isManager) return '🌙 管理员'
    var sp = item.starPoints || 0
    var level = Math.min(8, Math.floor(sp / 25) + 1)
    var tiers = ['⚪ 水星', '🟡 金星', '🌍 地球', '🔴 火星', '🟠 木星', '🪐 土星', '💠 天王星', '🌊 海王星']
    return tiers[level - 1] || ''
  },



  bindReplyInput: function(e) {
    this.setData({ replyContent: e.detail.value })
  },

  submitReply: function() {
    var that = this
    var content = that.data.replyContent.trim()
    var images = that.data.replyImages
    if (!content && images.length === 0) {
      wx.showToast({ title: '请输入回复内容或上传图片', icon: 'none' })
      return
    }
    var userInfo = app.globalData.userInfo || {}

    wx.showLoading({ title: '发送中' })

    that.uploadReplyImages().then(function(imageUrls) {
      var replyData = {
        action: 'replyPost',
        _id: that.data.postId,
        content: content,
        imageUrls: imageUrls,
        authorName: userInfo.nickName || '匿名用户',
        authorPhone: userInfo.phone || '',
        avatarColor: userInfo.avatarColor || '#0EA5E9',
        starPoints: userInfo.starPoints || 0,
        isAdmin: !!(userInfo.isAdmin),
        isManager: !!(userInfo.isManager)
      }

      if (that.data.quoteReply) {
        replyData.quoteContent = that.data.quoteReply.content || ''
        replyData.quoteFloor = that.data.quoteFloor
        replyData.quoteAuthor = that.data.quoteReply.authorName || '匿名用户'
      }

      wx.cloud.callFunction({
        name: 'login',
        data: replyData,
        success: function(res) {
          wx.hideLoading()
          if (res.result && res.result.code === 0) {
            that.setData({ replyContent: '', replyImages: [], replyMode: '', quoteReply: null, quoteFloor: 0 })
            wx.showToast({ title: '回复成功', icon: 'success' })
            that.loadPost(that.data.postId)
          } else {
            wx.showToast({ title: (res.result && res.result.msg) || '回复失败', icon: 'none' })
          }
        },
        fail: function() { wx.hideLoading(); wx.showToast({ title: '网络错误', icon: 'none' }) }
      })
    })
  },

  // 点击@回复某人
  tapReplyUser: function(e) {
    var index = e.currentTarget.dataset.index
    var replies = this.data.replies
    if (replies && replies[index]) {
      var reply = replies[index]
      this.setData({
        replyMode: 'reply',
        quoteReply: reply,
        quoteFloor: index + 1
      })
    }
  },

  // 点击引用内容
  tapQuoteReply: function(e) {
    var index = e.currentTarget.dataset.index
    var replies = this.data.replies
    if (replies && replies[index]) {
      var reply = replies[index]
      this.setData({
        replyMode: 'quote',
        quoteReply: reply,
        quoteFloor: index + 1
      })
    }
  },

  // 取消引用
  cancelQuote: function() {
    this.setData({ replyMode: '', quoteReply: null, quoteFloor: 0 })
  },

  togglePostContent: function() {
    this.setData({ postExpanded: !this.data.postExpanded })
  },

  toggleReply: function(e) {
    var index = e.currentTarget.dataset.index
    var expandedReplies = this.data.expandedReplies || {}
    expandedReplies[index] = !expandedReplies[index]
    this.setData({ expandedReplies: expandedReplies })
  },

  previewPostImage: function(e) {
    var url = e.currentTarget.dataset.url
    var media = e.currentTarget.dataset.urls || []
    var urls = []
    for (var i = 0; i < media.length; i++) {
      if (media[i].type === 'image') urls.push(media[i].url)
    }
    if (urls.length > 0 && url) {
      wx.previewImage({ urls: urls, current: url })
    }
  },

  onLikePost: function() {
    var that = this
    var postId = that.data.postId
    var post = that.data.post
    if (!postId) return
    if (post.isLiked) {
      wx.showToast({ title: '已经点赞过了', icon: 'none' })
      return
    }
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'likePost', _id: postId },
      success: function(res) {
        if (res.result && res.result.code === 0) {
          post.isLiked = true
          post.likeCount = (post.likeCount || 0) + 1
          that.setData({ post: post })
          wx.showToast({ title: '点赞成功', icon: 'success' })
        } else {
          wx.showToast({ title: (res.result && res.result.msg) || '点赞失败', icon: 'none' })
        }
      },
      fail: function() { wx.showToast({ title: '网络错误', icon: 'none' }) }
    })
  },

  onLikeReply: function(e) {
    var that = this
    var index = e.currentTarget.dataset.index
    var replies = that.data.replies
    var reply = replies[index]
    if (!reply) return
    if (reply.isLiked) {
      wx.showToast({ title: '已经点赞过了', icon: 'none' })
      return
    }
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'likeReply', _id: that.data.postId, replyIndex: index },
      success: function(res) {
        if (res.result && res.result.code === 0) {
          replies[index].isLiked = true
          replies[index].likeCount = (replies[index].likeCount || 0) + 1
          that.setData({ replies: replies })
          wx.showToast({ title: '点赞成功', icon: 'success' })
        } else {
          wx.showToast({ title: (res.result && res.result.msg) || '点赞失败', icon: 'none' })
        }
      },
      fail: function() { wx.showToast({ title: '网络错误', icon: 'none' }) }
    })
  },

  deleteReply: function(e) {
    var that = this
    var index = e.currentTarget.dataset.index
    wx.showModal({
      title: '确认删除',
      content: '确定删除该回复？',
      success: function(modal) {
        if (modal.confirm) {
          wx.cloud.callFunction({
            name: 'login',
            data: { action: 'deleteReply', _id: that.data.postId, index: index },
            success: function(res) {
              if (res.result && res.result.code === 0) {
                wx.showToast({ title: '已删除', icon: 'success' })
                that.loadPost(that.data.postId)
              } else {
                wx.showToast({ title: (res.result && res.result.msg) || '删除失败', icon: 'none' })
              }
            },
            fail: function() { wx.showToast({ title: '网络错误', icon: 'none' }) }
          })
        }
      }
    })
  },

  initEmoji: function () {
    this.setData({
      emojiTabs: EMOJI_TABS,
      emojiList: EMOJI_DATA.smile
    })
  },

  toggleEmoji: function () {
    var show = !this.data.showEmoji
    if (show && this.data.emojiList.length === 0) {
      this.initEmoji()
    }
    this.setData({ showEmoji: show })
  },

  switchEmojiTab: function (e) {
    var tabName = e.currentTarget.dataset.tab
    if (EMOJI_DATA[tabName]) {
      this.setData({ emojiList: EMOJI_DATA[tabName] })
    }
  },

  selectEmoji: function (e) {
    var emoji = e.currentTarget.dataset.emoji
    if (emoji) {
      this.setData({
        replyContent: this.data.replyContent + emoji
      })
    }
  },

  chooseImage: function () {
    var that = this
    wx.chooseImage({
      count: 3, sizeType: ['compressed'], sourceType: ['album', 'camera'],
      success: function (res) {
        var images = that.data.replyImages.concat(res.tempFilePaths)
        if (images.length > 3) images = images.slice(0, 3)
        that.setData({ replyImages: images })
      }
    })
  },

  removeReplyImage: function (e) {
    var index = e.currentTarget.dataset.index
    var images = this.data.replyImages
    images.splice(index, 1)
    this.setData({ replyImages: images })
  },

  uploadReplyImages: function () {
    var that = this
    var images = this.data.replyImages
    if (images.length === 0) return Promise.resolve([])

    var uploadPromises = images.map(function(path) {
      return commonUtil.compressImageToSize(path, 100).then(function(compressedPath) {
        return new Promise(function(resolve) {
          wx.cloud.uploadFile({
            cloudPath: 'reply-images/' + Date.now() + Math.floor(Math.random() * 9999) + '.jpg',
            filePath: compressedPath,
            success: function(up) { resolve(up.fileID) },
            fail: function() { resolve(null) }
          })
        })
      })
    })

    return Promise.all(uploadPromises).then(function(fileIDs) {
      return fileIDs.filter(function(id) { return id })
    })
  },

  previewImage: function(e) {
    var urls = e.currentTarget.dataset.urls
    var index = e.currentTarget.dataset.index || 0
    wx.previewImage({
      urls: urls,
      current: urls[index]
    })
  }
})
