// 吐槽广场页 - 显示帖子列表
const app = getApp()
var commonUtil = require('../../utils/common-util.js')
Page({
  data: {
    postList: [],
    loading: true,
    page: 0,
    hasMore: true,
    myOpenId: '',
    expandedPosts: {}
  },

  onLoad: function() {
    var userInfo = app.globalData.userInfo || {}
    this.setData({ myOpenId: userInfo._openid || '' })
    this.loadPosts()
  },

  onShow: function() {
    if (typeof this.getTabBar === 'function' && this.getTabBar()) {
      this.getTabBar().setData({ selected: 3 })
    }
    // 节流10秒
    var now = Date.now()
    if (now - (this.data.lastLoadTime || 0) > 10000) {
      this.setData({ lastLoadTime: now, page: 0, postList: [], hasMore: true })
      this.loadPosts()
    }
  },

  onPullDownRefresh: function() {
    var that = this
    // 清除缓存，强制刷新
    commonUtil.Cache.remove('forumPosts')
    that.setData({ page: 0, postList: [], hasMore: true })
    that.loadPosts(function() { wx.stopPullDownRefresh() })
  },

  onReachBottom: function() {
    if (this.data.hasMore && !this.data.loading) {
      this.loadMore()
    }
  },

  /**
   * 批量转换帖子中的图片 fileID 为临时 URL
   */
  convertPostImagesBatch: function(list) {
    var that = this
    var fileIDs = []
    var mappings = [] // { postIndex, mediaIndex }

    for (var i = 0; i < list.length; i++) {
      var post = list[i]
      if (!post.mediaList || post.mediaList.length === 0) continue
      for (var j = 0; j < post.mediaList.length; j++) {
        var media = post.mediaList[j]
        if (media.type === 'image' && media.url && media.url.indexOf('cloud://') === 0) {
          fileIDs.push(media.url)
          mappings.push({ postIndex: i, mediaIndex: j })
        }
      }
    }

    if (fileIDs.length === 0) return

    wx.cloud.getTempFileURL({
      fileList: fileIDs,
      success: function(res) {
        if (!res || !res.fileList) return
        var urlMap = {}
        for (var f = 0; f < res.fileList.length; f++) {
          var item = res.fileList[f]
          if (item.tempFileURL) {
            urlMap[item.fileID] = item.tempFileURL
          }
        }
        for (var m = 0; m < mappings.length; m++) {
          var map = mappings[m]
          var original = list[map.postIndex].mediaList[map.mediaIndex].url
          if (urlMap[original]) {
            list[map.postIndex].mediaList[map.mediaIndex].url = urlMap[original]
          }
        }
        // 强制刷新列表
        that.setData({ postList: list })
      }
    })
  },

  loadPosts: function(callback) {
    var that = this
    that.setData({ loading: true })

    // 先读缓存，快速展示
    var cachedPosts = commonUtil.Cache.get('forumPosts')
    if (cachedPosts && cachedPosts.length > 0) {
      that.setData({ postList: cachedPosts, loading: false })
    }

    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'getPosts', page: 0, limit: 15, myOpenId: that.data.myOpenId, school: (app.globalData.userInfo && app.globalData.userInfo.school) || '' },
      success: function(res) {
        if (res.result && res.result.code === 0) {
          var list = res.result.data || []
          list = list.map(function(p) {
            p.createTimeText = commonUtil.formatTime(p.createTime)
            p.replyCount = (p.replies && p.replies.length) || 0
            p.viewCount = p.viewCount || 0
            p.rankBadge = that.getRankBadge(p)
            p.isMe = !!p.isMine
            return p
          })
          that.setData({ postList: list, hasMore: list.length >= 15, page: 1 })
          // 异步转换图片URL
          that.convertPostImagesBatch(list)
          // 写入缓存，3分钟有效期
          commonUtil.Cache.set('forumPosts', list, 3)
        }
        that.setData({ loading: false })
        if (callback) callback()
      },
      fail: function() {
        that.setData({ loading: false })
        if (callback) callback()
      }
    })
  },

  loadMore: function() {
    var that = this
    that.setData({ loading: true })
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'getPosts', page: that.data.page, limit: 15, myOpenId: that.data.myOpenId, school: (app.globalData.userInfo && app.globalData.userInfo.school) || '' },
      success: function(res) {
        if (res.result && res.result.code === 0) {
          var list = res.result.data || []
          list = list.map(function(p) {
            p.createTimeText = commonUtil.formatTime(p.createTime)
            p.replyCount = (p.replies && p.replies.length) || 0
            p.viewCount = p.viewCount || 0
            p.rankBadge = that.getRankBadge(p)
            p.isMe = !!p.isMine
            return p
          })
          var newList = that.data.postList.concat(list)
          that.setData({ postList: newList, hasMore: list.length >= 15, page: that.data.page + 1 })
          // 异步转换新加载的图片URL
          that.convertPostImagesBatch(newList)
        }
        that.setData({ loading: false })
      },
      fail: function() { that.setData({ loading: false }) }
    })
  },

  getRankBadge: function(item) {
    if (item.isAdmin) return '👑 创始人'
    if (item.isManager) return '🌙 管理员'
    var sp = item.starPoints || 0
    var level = Math.min(8, Math.floor(sp / 25) + 1)
    var tiers = ['⚪ 水星', '🟡 金星', '🌍 地球', '🔴 火星', '🟠 木星', '🪐 土星', '💠 天王星', '🌊 海王星']
    return tiers[level - 1] || ''
  },

  togglePost: function(e) {
    var id = e.currentTarget.dataset.id
    var expandedPosts = this.data.expandedPosts || {}
    if (expandedPosts[id]) {
      expandedPosts[id] = false
    } else {
      expandedPosts[id] = true
    }
    this.setData({ expandedPosts: expandedPosts })
  },

  goPostDetail: function(e) {
    var id = e.currentTarget.dataset.id
    wx.navigateTo({ url: '/pages/post-detail/post-detail?id=' + id })
  },

  goNewPost: function() {
    wx.navigateTo({ url: '/pages/new-post/new-post' })
  },

  deleteMyPost: function(e) {
    var that = this
    var id = e.currentTarget.dataset.id
    wx.showModal({
      title: '确认删除',
      content: '确定删除该帖子？',
      success: function(modal) {
        if (modal.confirm) {
          wx.cloud.callFunction({
            name: 'login',
            data: { action: 'deletePost', _id: id },
            success: function(res) {
              if (res.result && res.result.code === 0) {
                wx.showToast({ title: '已删除', icon: 'success' })
                that.setData({ page: 0, postList: [] })
                that.loadPosts()
              }
            }
          })
        }
      }
    })
  }
})
