// 云函数：发送微信订阅消息通知
// 只允许云函数内部调用（其他云函数调用），或管理员直接调用
const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })
const db = cloud.database()

async function checkIsAdmin(openid) {
  try {
    const userRes = await db.collection('users').where({ _openid: openid }).get()
    if (userRes.data && userRes.data.length > 0) {
      var user = userRes.data[0]
      var isAdmin = user.isAdmin || user['isAdmin ']
      var isManager = user.isManager || user['isManager ']
      return !!(isAdmin || isManager)
    }
  } catch (e) {}
  return false
}

exports.main = async function(event, context) {
  try {
    const wxContext = cloud.getWXContext()
    const openid = wxContext.OPENID
    const { touser, templateId, page, data } = event

    if (!touser || !templateId) {
      return { code: -1, msg: '缺少参数' }
    }

    // 如果是云函数内部调用（FROMOPENID不存在），放行
    // 否则需要校验管理员权限
    if (openid) {
      var isAdmin = await checkIsAdmin(openid)
      // 允许给自己发通知（普通用户的通知场景）
      if (!isAdmin && touser !== openid) {
        return { code: -1, msg: '无权限发送通知给其他用户' }
      }
    }

    const result = await cloud.openapi.subscribeMessage.send({
      touser: touser,
      templateId: templateId,
      page: page || 'pages/orders/orders',
      data: data
    })

    return { code: 0, msg: '发送成功', result: result }
  } catch (err) {
    console.log('订阅消息发送失败:', err.message)
    return { code: -2, msg: '发送失败: ' + err.message }
  }
}
